(function(){
'use strict';
const D=window.EB,{icon:I,logo,art}=window.Visuals,$=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const STORAGE='ebex.prototype.v1.1';
let S,storageOK=true,focusBefore=null;
try{const saved=localStorage.getItem(STORAGE);S=saved?D.validateImport(JSON.parse(saved)):D.seed();if(!saved)localStorage.setItem(STORAGE,JSON.stringify(S));}catch(e){S=D.seed();storageOK=false;}
const ui={category:'all',query:'',sort:'relevant',condition:'',city:'',mode:'',min:'',max:'',onlyPremium:false,onlyVerified:false,filters:false,limit:8,checkout:null,chat:'c1',sellerTab:'active',orderTab:'all',draft:{step:1,photos:[],category:'tech',mode:'buy',condition:'Kao novo',city:'Beograd',weight:1,dims:[30,20,15]},tests:[],listingPhoto:null};
function e(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function fmt(n){return new Intl.NumberFormat('sr-Latn-RS',{maximumFractionDigits:2}).format(n/100);}
function date(x){return x?new Intl.DateTimeFormat('sr-Latn-RS',{timeZone:'Europe/Belgrade',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(x)):'—';}
function stamp(x){return x?new Intl.DateTimeFormat('sr-Latn-RS',{timeZone:'Europe/Belgrade',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(x)):'—';}
function amount(x){const n=String(x||'').trim().replace(',','.');return /^\d+(\.\d{1,2})?$/.test(n)?Math.round(Number(n)*100):NaN;}
function label(x){return ({AWAITING_SHIPMENT:'Čeka predaju',IN_TRANSIT:'Na putu',DELIVERED_COD_COLLECTED:'Uručeno · naplaćeno',REMITTANCE_PENDING:'Čeka BEX isplatu',PAYOUT_HOLD:'Isplata zaustavljena',COMPLETED:'Završeno',CANCELLED:'Otkazano',SHIPMENT_EXPIRED:'Istekao rok predaje',MANUAL_REVIEW:'Ručni pregled',RETURN_REQUIRED:'Povrat odobren',RETURN_IN_TRANSIT:'Povrat na putu',RETURNED:'Predmet vraćen',COD_REFUNDED:'Pouzeće vraćeno',CREATED:'Kreirana',DELIVERED:'Uručena',PENDING:'Na čekanju',COLLECTED:'Naplaćeno',PAID:'Isplaćeno',NOT_DUE:'Čeka uručenje',HOLD_CONFIRMED:'Zadržano · BEX potvrda',HOLD_REQUESTED:'Zadržavanje zatraženo',ACTIVE:'Aktivan',RESERVED:'Rezervisan',SOLD:'Prodat',PAUSED:'Pauziran',PENDING_REVIEW:'Na pregledu',REMOVED:'Uklonjen',OPEN:'Otvoren',EVIDENCE_REQUESTED:'Čeka dodatne dokaze',RETURN_APPROVED:'Povrat odobren',RESOLVED:'Rešen',NONE:'Nije pokrenuto',REFUNDED:'Vraćeno',REQUIRED:'Potreban',ACCEPTED:'Prihvaćena',SUPERSEDED:'Zamenjena',CONVERTED:'Kupovina potvrđena'})[x]||x;}
function badge(x){const color=/HOLD|REVIEW|RETURN_REQUIRED/.test(x)?'orange':/COMPLETED|PAID|COLLECTED|ACTIVE|RESOLVED|REFUNDED|ACCEPTED/.test(x)?'green':/CANCEL|REMOVED|EXPIRED/.test(x)?'gray':'';return '<span class="badge '+color+'">'+e(label(x))+'</span>';}
function btn(text,action,data='',cls=''){return '<button class="btn '+cls+'" data-action="'+action+'" '+data+'>'+text+'</button>';}
function link(text,path,cls='btn secondary'){return '<a class="'+cls+'" href="#/'+path+'">'+text+'</a>';}
function img(l){return l.photos?.length&&/^data:image\/(?:jpeg|png|webp);base64,/.test(l.photos[0])?l.photos[0]:art(l.art||'box');}
function photoSrc(src,l){return /^data:image\/(?:jpeg|png|webp);base64,/.test(src||'')?src:img(l);}
function alertBox(text,color='',icon='shield'){return '<div class="tagline '+color+'">'+I(icon)+'<span>'+text+'</span></div>';}
function empty(title,text,action=''){return '<div class="empty">'+I('box')+'<h3>'+title+'</h3><p>'+text+'</p>'+action+'</div>';}
function head(title,sub,action=''){return '<div class="page-head"><div><h1>'+title+'</h1><p>'+sub+'</p></div>'+action+'</div>';}
function crumb(text){return '<div class="breadcrumbs"><a href="#/market">Početna</a>'+I('chevron')+'<span>'+text+'</span></div>';}
function stat(title,value,note,icon){return '<div class="stat"><div class="label">'+I(icon)+' '+title+'</div><div class="value">'+value+'</div><div class="note">'+note+'</div></div>';}
function toast(text,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=I(error?'info':'checkCircle')+'<span>'+e(text)+'</span><button aria-label="Zatvori obaveštenje">'+I('close')+'</button>';el.querySelector('button').onclick=()=>el.remove();$('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
function commit(fn){const next=D.clone(S);const result=fn(next);next.revision=(S.revision||0)+1;if(storageOK){try{localStorage.setItem(STORAGE,JSON.stringify(next));}catch(err){throw Error('Nema dovoljno mesta u pregledaču. Izvezi test i dodaj manje fotografija.');}}S=next;return result;}
function route(){return location.hash.replace(/^#\/?/,'').split('/');}
function go(path){if(location.hash==='#/'+path)render();else location.hash='/'+path;}
function setRole(role,path){commit(s=>{s.session.role=role;D.audit(s,'DEMO','ROLE_SWITCH',role);});closeModal();if(path)go(path);else render();}
function header(){const r=route(),section=r[0]||'market',me=S.users.me,unread=S.notifications.filter(n=>!n.read).length;return `
<div class="topbar"><div class="row"><span>${I('leaf')} Dobri predmeti zaslužuju drugu priču.</span></div><div class="row toplinks"><span>${I('truck')} Dostavlja BEX</span><button data-action="help">Kako funkcioniše</button></div><span><span class="dot"></span>Test okruženje · podaci su probni</span></div>
<header class="header"><a class="logo" href="#/market" aria-label="eBex početna">${logo()}</a><form class="search" id="search-form" role="search">${I('search')}<input id="global-search" name="q" type="search" value="${e(ui.query)}" placeholder="Pronađi nešto baš za sebe…" aria-label="Pretraži oglase"><span class="keycap">↵</span></form><div class="header-actions"><a class="navicon" href="#/favorites" aria-label="Sačuvani oglasi">${I('heart')}${S.favorites.length?'<em>'+S.favorites.length+'</em>':''}</a><a class="navicon" href="#/messages" aria-label="Poruke">${I('chat')}<em>${S.conversations.filter(c=>c.unread).length||''}</em></a><button class="navicon" data-action="notifications" aria-label="Obaveštenja">${I('bell')}${unread?'<em>'+unread+'</em>':''}</button><div class="divider-v"></div><button class="account-trigger" data-action="account" aria-label="Profil i testne uloge"><span class="avatar">${e(me.initials)}</span><span>${e(me.name.split(' ')[0])}<br><small>${({buyer:'Kupac',seller:'Prodavac',admin:'Administrator'})[S.session.role]} · testni nalog</small></span>${I('down')}</button><a class="btn" href="#/sell">${I('plus')} Postavi oglas</a></div></header>
<nav class="navbar" aria-label="Glavna navigacija"><a href="#/market" class="${section==='market'||section==='listing'?'active':''}">${I('grid')} Istraži oglase</a><a href="#/orders" class="${section==='orders'?'active':''}">${I('box')} Moje kupovine</a><a href="#/seller" class="${section==='seller'?'active':''}">${I('tag')} Moja prodaja</a><a href="#/premium" class="${section==='premium'?'active':''}">${I('spark')} Premium</a><a href="#/test" class="${section==='test'?'active':''}">${I('play')} Test centar</a><a href="#/admin/overview" class="${section==='admin'?'active':''}">${I('sliders')} Administracija</a><span class="nav-right">${I('shield')} Kupuješ kroz eBex. Plaćaš BEX kuriru.</span></nav>`;}
function footer(){return `<footer class="footer"><div class="row"><a class="logo" href="#/market">${logo()}</a><span>Nova prilika za dobre stvari.</span></div><div class="row"><button data-action="help">Kako radi</button><a href="#/test">Uputstvo za testiranje</a><button data-action="privacy">Privatnost</button><span class="footer-extra">© ${new Date().getFullYear()} eBex · BEX ekosistem</span></div></footer><nav class="mobile-nav" aria-label="Mobilna navigacija"><a href="#/market" class="${route()[0]==='market'?'active':''}">${I('search')}Istraži</a><a href="#/favorites" class="${route()[0]==='favorites'?'active':''}">${I('heart')}Sačuvano</a><a href="#/sell" class="sell-mobile" aria-label="Postavi oglas">${I('plus')}Oglas</a><a href="#/orders" class="${route()[0]==='orders'?'active':''}">${I('box')}Kupovine</a><button data-action="account">${I('user')}Moj nalog</button></nav>`;}
function card(l){const seller=S.users[l.seller]||S.users.me,price=fmt(l.price);return `<article class="product"><a class="product-image" href="#/listing/${e(l.id)}"><img src="${e(img(l))}" alt="${e(l.title)}" loading="lazy">${D.effectivePremium(l,S)?'<span class="premium-badge">'+I('spark')+' PROMOVISANO</span>':''}</a><button class="favorite ${S.favorites.includes(l.id)?'selected':''}" data-action="favorite" data-id="${e(l.id)}" aria-label="${S.favorites.includes(l.id)?'Ukloni iz':'Dodaj u'} omiljene: ${e(l.title)}" aria-pressed="${S.favorites.includes(l.id)}">${I('heart')}</button><div class="product-body"><div class="product-meta"><span>${I('pin')}${e(l.city)}</span><span>${e(l.condition)}</span></div><a class="product-title" href="#/listing/${e(l.id)}">${e(l.title)}</a><div class="product-price">${price}<small>RSD</small></div><div class="product-footer"><span class="row">${I('shield')}${seller.phone?'Potvrđen telefon':'Novi član'}</span><span class="mode-tag">${l.mode==='buy'?'Kupi odmah':'Dogovori cenu'}</span></div></div></article>`;}
function categoryStrip(){return '<div class="category-strip">'+D.categories.map(c=>`<button class="category ${ui.category===c.id?'active':''}" data-action="category" data-id="${c.id}">${I(c.icon)}<span>${c.name}</span></button>`).join('')+'</div>';}
function home(favorites=false){
 const n=D.normalized(ui.query),syn=n.replace(/slusalice|sluske/g,'sony').replace(/fotoaparat|foto aparat/g,'fujifilm').replace(/patike/g,'nike').replace(/biljka/g,'monstera');
 let ls=S.listings.filter(l=>l.status==='ACTIVE'&&(!favorites||S.favorites.includes(l.id))&&(ui.category==='all'||l.category===ui.category)&&(!n||D.normalized(l.title+' '+l.description+' '+l.city).includes(n)||D.normalized(l.title).includes(syn))&&(!ui.condition||l.condition===ui.condition)&&(!ui.city||l.city===ui.city)&&(!ui.mode||l.mode===ui.mode)&&(!ui.min||l.price>=amount(ui.min))&&(!ui.max||l.price<=amount(ui.max))&&(!ui.onlyPremium||D.effectivePremium(l,S))&&(!ui.onlyVerified||S.users[l.seller]?.phone));
 if(ui.sort==='price-asc')ls.sort((a,b)=>a.price-b.price);else if(ui.sort==='price-desc')ls.sort((a,b)=>b.price-a.price);else if(ui.sort==='new')ls.sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));else ls.sort((a,b)=>Number(!!D.effectivePremium(b,S))-Number(!!D.effectivePremium(a,S))||b.views-a.views);
 const filterCount=[ui.condition,ui.city,ui.mode,ui.min,ui.max].filter(Boolean).length;
 return `${favorites?head('Tvoji sačuvani favoriti','Dobre stvari koje su ti privukle pažnju.'):!ui.query?`<section class="hero"><div class="hero-copy"><div class="eyebrow">MALO OTKRIĆE. DOBRA KUPOVINA.</div><h1>Nekome višak.<br>Tebi <em>baš to.</em></h1><p>Kupi ono što tražiš, prodaj ono što ne koristiš.<br>Mi povezujemo ljude. BEX donosi na vrata.</p><div class="hero-buttons"><a class="btn" href="#/sell">Postavi besplatan oglas ${I('arrow')}</a><button class="text-btn" data-action="help">Kako funkcioniše ${I('chevron')}</button></div><span class="micro">${I('checkCircle')} Besplatni oglasi · Samo BEX · Plaćanje pouzećem</span></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="hero-tile one"><img src="${art('headphones')}" alt=""><div class="row between"><span>Zvuk za svaki dan.</span><strong>23.500 RSD</strong></div></div><div class="hero-tile two"><img src="${art('camera')}" alt=""><div class="row between"><span>Nove uspomene.</span><strong>69.000 RSD</strong></div></div><div class="hero-tile three"><img src="${art('sneaker')}" alt=""><div class="row between"><span>Drugi krug.</span><strong>7.900 RSD</strong></div></div><div class="floating-label">${I('shield')} Lepše je kad kupuješ sigurno.</div></div></section><div class="benefits">${[['tag','Oglasi su besplatni','Za sve fizičke prodavce.'],['truck','BEX na tvojim vratima','Jednostavna dostava širom Srbije.'],['wallet','Plaćaš kad stigne','Isključivo pouzećem pri uručenju.'],['chat','Sve na jednom mestu','Dogovor i podrška u aplikaciji.']].map(a=>'<div class="benefit">'+I(a[0])+'<div><strong>'+a[1]+'</strong><span>'+a[2]+'</span></div></div>').join('')}</div>`:head('Rezultati za „'+e(ui.query)+'”',ls.length+' oglasa odgovara tvojoj pretrazi.',btn('Sačuvaj pretragu','save-search','','secondary'))}
 ${!favorites?'<div class="section-heading"><div><h2>Šta danas tražiš?</h2><p>Od malih želja do velikih pronalazaka.</p></div><button class="text-btn" data-action="all-categories">Sve kategorije '+I('arrow')+'</button></div>'+categoryStrip():''}
 <div class="section-heading"><div><h2>${favorites?'Sačuvano za kasnije':ui.query?'Pronađeni oglasi':ui.category==='all'?'Izdvojeno za tebe':e(D.categories.find(c=>c.id===ui.category)?.name)}</h2><p>${ls.length} ${ls.length===1?'oglas':'oglasa'} · sve cene su u RSD</p></div>${!favorites?btn(I('heart')+' Sačuvaj pretragu','save-search','','ghost small'):''}</div>
 <div class="market-toolbar"><div class="chips">${btn(I('sliders')+' Filteri'+(filterCount?' · '+filterCount:''),'filters','','chip '+(ui.filters?'active':''))}${btn(I('shield')+' Potvrđeni prodavci','verified','','chip '+(ui.onlyVerified?'active':''))}${btn(I('spark')+' Premium','premium-filter','','chip '+(ui.onlyPremium?'active':''))}${filterCount||ui.category!=='all'||ui.onlyPremium||ui.onlyVerified?btn('Poništi '+I('close'),'clear-filters','','chip'):''}</div><div class="sorter"><label for="sorter">Sortiraj:</label><select id="sorter" data-change="sort"><option value="relevant" ${ui.sort==='relevant'?'selected':''}>Preporučeno</option><option value="new" ${ui.sort==='new'?'selected':''}>Najnovije</option><option value="price-asc" ${ui.sort==='price-asc'?'selected':''}>Cena: rastuće</option><option value="price-desc" ${ui.sort==='price-desc'?'selected':''}>Cena: opadajuće</option></select></div></div>
 ${ui.filters?`<form id="filter-form" class="filters-panel"><label class="field">Cena od (RSD)<input name="min" inputmode="decimal" value="${e(ui.min)}" placeholder="0"></label><label class="field">Cena do (RSD)<input name="max" inputmode="decimal" value="${e(ui.max)}" placeholder="Bez ograničenja"></label><label class="field">Stanje<select name="condition"><option value="">Sva stanja</option>${['Novo','Kao novo','Odlično','Dobro'].map(c=>'<option '+(ui.condition===c?'selected':'')+'>'+c+'</option>').join('')}</select></label><label class="field">Grad<select name="city"><option value="">Svi gradovi</option>${[...new Set(S.listings.map(l=>l.city))].map(c=>'<option '+(ui.city===c?'selected':'')+'>'+e(c)+'</option>').join('')}</select></label><label class="field">Režim<select name="mode"><option value="">Svi oglasi</option><option value="buy" ${ui.mode==='buy'?'selected':''}>Kupi</option><option value="contact" ${ui.mode==='contact'?'selected':''}>Kontaktiraj me</option></select></label><button class="btn small" type="submit">Primeni</button></form>`:''}
 ${ls.length?'<div class="product-grid">'+ls.slice(0,ui.limit).map(card).join('')+'</div>':empty('Još nema takvih oglasa.','Promeni filtere ili pretragu i pronađi nešto drugo.',btn('Poništi filtere','clear-filters','','secondary'))}
 ${ls.length>ui.limit?'<div class="load-more">'+btn('Prikaži još oglasa '+I('down'),'load-more','','secondary')+'</div>':''}
 ${!favorites&&!ui.query?'<div class="banner">'+I('leaf')+'<div class="grow"><h3>Ne koristiš? Neko baš to traži.</h3><p>Fotografiši, postavi oglas i prepusti dostavu BEX-u.</p></div><a class="btn secondary" href="#/sell">Prodaj nešto svoje '+I('arrow')+'</a></div>':''}`;
}
function detail(id){const l=S.listings.find(l=>l.id===id);if(!l)return empty('Oglas nije pronađen.','Vrati se na pretragu.',link('Istraži oglase','market'));const u=S.users[l.seller]||S.users.me,cat=D.categories.find(c=>c.id===l.category);const own=l.seller==='me';return `${crumb(e(cat?.name||'Oglas'))}<div class="detail-grid"><div><div class="detail-image"><img id="detail-main-image" src="${e(ui.listingPhoto||img(l))}" alt="${e(l.title)}"><button class="favorite ${S.favorites.includes(l.id)?'selected':''}" data-action="favorite" data-id="${e(l.id)}" aria-label="Sačuvaj oglas">${I('heart')}</button></div><div class="thumbs">${(l.photos.length?l.photos:[img(l)]).map((p,i)=>'<button data-action="photo" data-id="'+e(l.id)+'" data-index="'+i+'" class="'+(!i?'active':'')+'" aria-label="Fotografija '+(i+1)+'"><img src="'+e(photoSrc(p,l))+'" alt=""></button>').join('')}</div><div class="spacer"></div>${alertBox('Adresa prodavca i kontakt podaci nisu javni. Dogovor se odvija u eBex porukama.','','shield')}</div><div class="detail-info"><div class="row between"><div class="row gap8">${badge(l.status)}${D.effectivePremium(l,S)?'<span class="badge orange">'+I('spark')+' Promovisano</span>':''}</div><button class="text-btn muted" data-action="report-listing" data-id="${e(id)}">${I('flag')} Prijavi</button></div><h1 class="title">${e(l.title)}</h1><div class="row gap8 small muted">${I('pin','icon-sm')} ${e(l.city)} <span>·</span> ${e(l.condition)}</div><div class="spacer"></div><div class="price">${fmt(l.price)} <small>RSD</small></div><p class="sub">${l.mode==='contact'?'Dogovori cenu kroz eBex ponudu.':'Cena predmeta · BEX dostava se obračunava pri kupovini.'}</p><div class="seller-card"><span class="avatar sage">${e(u.initials)}</span><div><div class="name">${e(u.name)} ${u.phone?I('checkCircle','icon-sm text-green'):''}</div><div class="meta">${u.trades} uspešnih prodaja · član od ${u.since}.</div></div><div class="rating">${I('star')} ${u.rating.toFixed(1)}</div></div><p class="description">${e(l.description)}</p><div class="detail-attrs"><div><span>Stanje</span><b>${e(l.condition)}</b></div><div><span>Kategorija</span><b>${e(cat?.name)}</b></div><div><span>Masa paketa</span><b>${e(l.weight)} kg</b></div><div><span>Način plaćanja</span><b>Pouzeće</b></div></div><div class="buy-box"><div class="row">${I('truck')} <span class="grow">Isključivo BEX dostava</span><b>od ${D.money(D.quote(S,l.weight,'shop'))}</b></div><small class="muted">Procena iz testnog cenovnika, nije zvanična BEX ponuda.</small>${own?link('Upravljaj svojim oglasom','seller'):l.status!=='ACTIVE'?'<button class="btn" disabled>Predmet trenutno nije dostupan</button>':l.mode==='buy'?btn('Kupi za '+D.money(l.price)+' '+I('arrow'),'checkout','data-id="'+e(id)+'"','large'):btn(I('chat')+' Kontaktiraj prodavca','contact','data-id="'+e(id)+'"','large')}${!own&&l.mode==='buy'&&l.status==='ACTIVE'?btn(I('chat')+' Pitaj prodavca','contact','data-id="'+e(id)+'"','secondary'):''}<p>${I('shield','icon-sm')} Plaćaš BEX kuriru pri uručenju.<br>Reklamaciju i eventualni povrat rešavaš kroz eBex.</p></div></div></div><div class="section-heading"><div><h2>Možda ti se dopadne i ovo</h2><p>Još dobrih stvari iz iste kategorije.</p></div></div><div class="product-grid related">${S.listings.filter(x=>x.id!==id&&x.status==='ACTIVE'&&x.category===l.category).slice(0,4).map(card).join('')||card(S.listings.find(x=>x.id!==id&&x.status==='ACTIVE'))}</div>`;}
function checkoutView(){const c=ui.checkout,l=S.listings.find(l=>l.id===c?.id);if(!l)return empty('Izaberi predmet za kupovinu.','Korpa nije potrebna: svaki C2C predmet se kupuje zasebno.',link('Istraži oglase','market'));const shipping=D.quote(S,l.weight,c.delivery||'home'),price=c.price||l.price;return `${crumb('Potvrdi kupovinu')}${head('Još korak do dobre kupovine.','Plaćaš tek pri uručenju, direktno BEX kuriru.')}<div class="checkout-layout"><form id="checkout-form" class="panel stack"><div data-error></div><div class="form-section"><h3>1. Gde šaljemo?</h3><div class="form-grid"><label class="field full-span">Ime i prezime<input name="name" value="Ana Petrović" required maxlength="80" autocomplete="off"></label><label class="field full-span">Ulica i broj<input name="street" value="Test adresa 1" required maxlength="120" autocomplete="off"></label><label class="field">Grad<input name="city" value="Beograd" required maxlength="60"></label><label class="field">Poštanski broj<input name="postal" value="11000" required pattern="[0-9]{5}" inputmode="numeric"></label></div><p class="readonly-note">Koristi isključivo izmišljene podatke za testiranje.</p></div><div class="form-section"><h3>2. BEX dostava</h3><div class="stack"><label class="radio-card"><input type="radio" name="delivery" value="home" ${c.delivery!=='shop'?'checked':''} data-change="delivery"><div class="grow"><b>Na adresu</b><p>BEX kurir dostavlja na unetu testnu adresu.</p></div><b>${D.money(D.quote(S,l.weight,'home'))}</b></label><label class="radio-card"><input type="radio" name="delivery" value="shop" ${c.delivery==='shop'?'checked':''} data-change="delivery"><div class="grow"><b>BEX Paket Shop · demo lokacija</b><p>Test centar Beograd · testna dostupnost za ovaj paket.</p></div><b>${D.money(D.quote(S,l.weight,'shop'))}</b></label></div><p class="readonly-note">Paket Shop i cene su simulirani. Dostupnost se u produkciji potvrđuje preko BEX-a.</p></div><div class="form-section"><h3>3. Plaćanje</h3><label class="radio-card"><input type="radio" checked name="payment" value="BEX_COD"><div><b>Pouzećem BEX kuriru</b><p>Ukupan iznos plaćaš pri uručenju. eBex ne prima i ne čuva tvoj novac.</p></div>${I('wallet')}</label></div><label class="checkline"><input type="checkbox" name="terms" required><span>Potvrđujem testnu kupovinu i razumem pravila BEX dostave, pouzeća i reklamacije. Ovo ne stvara stvarnu porudžbinu.</span></label><button type="submit" class="btn large">Potvrdi testnu kupovinu ${I('arrow')}</button></form><aside class="panel summary-card stack"><h3>Tvoja kupovina</h3><div class="checkout-product"><img src="${e(img(l))}" alt=""><div><h3>${e(l.title)}</h3><p class="small muted">${e(S.users[l.seller]?.name)} · ${e(l.condition)}</p></div></div><div class="price-summary"><div class="row"><span class="muted">Cena predmeta</span><b>${D.money(price)}</b></div><div class="row"><span class="muted">BEX dostava · demo</span><b id="shipping-summary">${D.money(shipping)}</b></div><div class="row"><span class="muted">eBex provizija</span><b>0 RSD</b></div><div class="row total"><span>Ukupno pouzeće</span><span id="total-summary">${D.money(price+shipping)}</span></div></div>${alertBox('Ako se pre isplate evidentira reklamacija ili sumnja na prevaru, pokreće se zadržavanje BEX isplate prodavcu.','','shield')}<p class="small muted">Procene, rokovi i lokacije u ovom prototipu služe testiranju i nisu ugovorni uslovi BEX-a.</p></aside></div>`;}
function ordersView(id){if(id)return orderDetail(id);let os=S.orders.filter(o=>S.session.role==='seller'?o.seller==='me':o.buyer==='me');if(ui.orderTab==='active')os=os.filter(o=>!['COMPLETED','CANCELLED','COD_REFUNDED','SHIPMENT_EXPIRED'].includes(o.status));if(ui.orderTab==='closed')os=os.filter(o=>['COMPLETED','CANCELLED','COD_REFUNDED','SHIPMENT_EXPIRED'].includes(o.status));if(ui.orderTab==='disputes')os=os.filter(o=>o.dispute);return `${crumb('Porudžbine')}${head(S.session.role==='seller'?'Tvoje prodaje.':'Tvoje kupovine.','Od potvrde do uručenja — sve pratiš ovde.',link(I('play')+' Testiraj ceo proces','test','btn secondary'))}<div class="tabs">${[['all','Sve porudžbine'],['active','U toku'],['closed','Završene'],['disputes','Reklamacije']].map(a=>'<button class="'+(ui.orderTab===a[0]?'active':'')+'" data-action="order-tab" data-id="'+a[0]+'">'+a[1]+'</button>').join('')}</div>${os.length?os.slice().reverse().map(o=>orderCard(o)).join(''):empty('Ovde će biti tvoje porudžbine.','Probaj da kupiš predmet ili pokreni scenario u Test centru.',link('Istraži oglase','market'))}`;}
function orderCard(o){return `<article class="order-card"><div class="top row between"><b>${e(o.id)}</b><span>${date(o.createdAt)}</span>${badge(o.status)}</div><div class="item"><img class="list-thumb" src="${e(img(o.snapshot))}" alt=""><div class="grow"><h3>${e(o.snapshot.title)}</h3><p class="small muted">${o.seller==='me'?'Kupac: '+e(S.users[o.buyer]?.name||'Test kupac'):'Prodavac: '+e(S.users[o.seller]?.name||'Test prodavac')}</p><span class="small muted">BEX · pouzećem</span></div><div class="price">${D.money(o.total)}</div></div><div class="bottom"><span class="muted">${I('truck','icon-sm')} ${e(label(o.shipmentStatus))}</span><span class="muted">${I('wallet','icon-sm')} ${e(label(o.payoutStatus))}</span>${link('Detalji '+I('arrow'),'orders/'+o.id,'btn secondary small')}</div></article>`;}
function orderDetail(id){const o=S.orders.find(o=>o.id===id);if(!o)return empty('Porudžbina nije pronađena.','Proveri spisak porudžbina.',link('Moje kupovine','orders'));const s=S.users[o.seller]||S.users.me,proof=o.proofRequired;const isAdmin=S.session.role==='admin';return `${crumb('Porudžbina '+e(id))}<div class="page-head"><div class="order-detail-title"><img src="${e(img(o.snapshot))}" alt=""><div><h1>${e(id)}</h1><p>${e(o.snapshot.title)}</p></div></div>${badge(o.status)}</div><div class="checkout-layout"><div class="stack"><section class="panel stack"><div class="row between"><h3>Status porudžbine</h3><span class="badge gray">${I('truck')} BEX simulacija</span></div><div class="finance-status"><div><div class="label">Dostava</div><div class="value">${e(label(o.shipmentStatus))}</div></div><div><div class="label">Pouzeće</div><div class="value">${e(label(o.codStatus))}</div></div><div><div class="label">Isplata prodavcu</div><div class="value">${e(label(o.payoutStatus))}</div></div></div>${o.dispute?alertBox(o.dispute.afterPayout?'Reklamacija je prijavljena nakon izvršene isplate. Novac nije zamrznut; potreban je ručni pregled.':o.payoutStatus==='HOLD_REQUESTED'?'Zadržavanje je zatraženo, ali BEX potvrda nije dostupna. Isplata u prototipu ostaje blokirana.':'Reklamacija je evidentirana. Simulirana BEX potvrda zadržavanja sprečava isplatu.','orange','flag'):''}<div class="small muted">${I('box','icon-sm')} Broj pošiljke: <b>${e(o.shipment)}</b></div><div class="timeline">${o.events.slice().reverse().map(x=>'<div class="timeline-row"><span class="timeline-dot">'+I('check')+'</span><div><div class="title">'+e(x.text)+'</div><div class="time">'+stamp(x.at)+' · Europe/Belgrade</div></div></div>').join('')}</div></section><section class="panel stack"><div class="row between"><h3>Pakovanje i dokazi</h3><span class="badge ${proof?'orange':'gray'}">${proof?'Dokaz je obavezan':'Dokaz je preporučen'}</span></div><p class="small muted">Predmet, serijski broj ako postoji, zaštitni materijal i zatvoren paket. U ovom prototipu prihvataju se fotografije.</p>${o.evidence.length?'<div class="photo-list">'+o.evidence.map(p=>p.data?'<img src="'+e(photoSrc(p.data,o.snapshot))+'" alt="'+e(p.name)+'">':'<span class="badge green">'+I('image')+e(p.name)+'</span>').join('')+'</div>':alertBox('Dokaz još nije dodat.'+(proof?' BEX predaja je blokirana.':''),'orange','image')}${o.shipmentStatus==='CREATED'?(S.session.role==='seller'||isAdmin?`<label class="field">Dodaj fotografije pakovanja<input type="file" data-upload="proof" data-id="${e(id)}" accept="image/jpeg,image/png,image/webp" multiple></label>${btn('Koristi demo dokaz pakovanja','demo-proof','data-id="'+e(id)+'"','secondary small')}`:btn('Testiraj ovaj korak kao prodavac','role-for-order','data-role="seller" data-id="'+e(id)+'"','secondary')):''}</section>${o.dispute?`<section class="panel stack"><div class="row between"><h3>Reklamacija</h3>${badge(o.dispute.status)}</div><b class="small">${e(o.dispute.reason)}</b><p class="small muted">${e(o.dispute.description)}</p>${o.dispute.evidence?.length?'<div class="photo-list">'+o.dispute.evidence.map(p=>'<img src="'+e(photoSrc(p.data,o.snapshot))+'" alt="'+e(p.name)+'">').join('') :''}${o.returnShipment?alertBox('BEX povratna pošiljka: <b>'+e(o.returnShipment)+'</b>. Povraćaj pouzeća čeka uručenje povrata i odluku.','blue','truck'):''}${isAdmin?`<form id="dispute-decision" data-id="${e(id)}" class="stack"><div data-error></div><label class="field">Odluka<select name="decision"><option value="evidence">Zatraži dodatni dokaz</option><option value="return">Odobri BEX povrat</option><option value="release">Ukini zadržavanje isplate</option></select></label><label class="field">Obavezno obrazloženje<textarea name="reason" minlength="10" required placeholder="Obrazloži pregled dokaza i odluku…"></textarea></label><button type="submit" class="btn secondary">Evidentiraj testnu odluku</button><p class="readonly-note">Finansijske akcije zavise od administratorske uloge. Svaka odluka ostavlja revizijski trag.</p></form>`:link('Otvori u administraciji','admin/disputes','btn secondary small')}</section>`:''}</div><aside class="stack summary-card"><section class="panel stack"><h3>Pregled iznosa</h3><div class="price-summary"><div class="row"><span class="muted">Predmet</span><b>${D.money(o.price)}</b></div><div class="row"><span class="muted">BEX dostava · demo</span><b>${D.money(o.shipping)}</b></div><div class="row total"><span>Ukupno pouzeće</span><span>${D.money(o.total)}</span></div></div><div class="small muted">Prodavac: <b>${e(s.name)}</b><br>Račun: ${s.bank?'testno potvrđen':'nije potvrđen'}<br>Očekivana isplata: ${o.payoutDueAt?date(o.payoutDueAt):'nakon uručenja + testni rok'}</div>${alertBox('Isplatu i naplatu izvršava BEX. Prikazani statusi i iznosi u prototipu su simulacija.','','wallet')}${!o.dispute&&!['CANCELLED','SHIPMENT_EXPIRED','COD_REFUNDED'].includes(o.status)?btn(I('flag')+' Prijavi problem','complaint','data-id="'+e(id)+'"','secondary'):''}${o.status==='COMPLETED'&&!S.ratings.some(r=>r.orderId===id)?btn(I('star')+' Oceni kupovinu','review','data-id="'+e(id)+'"','secondary'):''}</section><details class="test-controls" open><summary class="strong small">${I('play','icon-sm')} Testne komande · BEX simulator</summary><p>Ove radnje ne pozivaju stvarni BEX. Pomeri testni sat da proveriš rok isplate.</p><div class="row wrap gap8">${btn('BEX preuzeo','simulate','data-id="'+e(id)+'" data-type="TRANSIT"','secondary small')}${btn('Uručeno + naplaćeno','simulate','data-id="'+e(id)+'" data-type="DELIVERED"','secondary small')}${btn('+1 dan','advance-day','','secondary small')}${btn('Potvrdi BEX isplatu','simulate','data-id="'+e(id)+'" data-type="PAYOUT"','secondary small')}${btn('Ponovi poslednji događaj','duplicate','data-id="'+e(id)+'"','secondary small')}${o.shipmentStatus==='CREATED'?btn('Otkaži pre predaje','simulate','data-id="'+e(id)+'" data-type="CANCEL"','secondary small')+btn('Proveri istek predaje','simulate','data-id="'+e(id)+'" data-type="EXPIRE"','secondary small'):''}${o.returnStatus==='REQUIRED'?btn('BEX preuzeo povrat','simulate','data-id="'+e(id)+'" data-type="RETURN_TRANSIT"','secondary small'):''}${o.returnStatus==='IN_TRANSIT'?btn('Povrat uručen prodavcu','simulate','data-id="'+e(id)+'" data-type="RETURN_DELIVERED"','secondary small'):''}${o.refundStatus==='PENDING'?btn('Potvrdi BEX COD povraćaj','simulate','data-id="'+e(id)+'" data-type="REFUND"','secondary small'):''}</div><p>Testni pomak: +${Math.round(S.clock/864e5)} dana · ${link('sve testne porudžbine','test','text-btn')}</p></details><div class="row wrap gap8">${btn('Uloga kupca','role-for-order','data-role="buyer" data-id="'+e(id)+'"','ghost small')}${btn('Uloga prodavca','role-for-order','data-role="seller" data-id="'+e(id)+'"','ghost small')}${btn('Uloga admina','role-for-order','data-role="admin" data-id="'+e(id)+'"','ghost small')}</div>${btn(I('download')+' Preuzmi testnu nalepnicu','label','data-id="'+e(id)+'"','ghost small')}</aside></div>`;}

function sellerView(){const own=S.listings.filter(l=>l.seller==='me'),sales=S.orders.filter(o=>o.seller==='me');let ls=own.filter(l=>ui.sellerTab==='all'||(ui.sellerTab==='active'?['ACTIVE','RESERVED'].includes(l.status):ui.sellerTab==='paused'?l.status==='PAUSED':l.status==='SOLD'));return `${crumb('Moja prodaja')}${head('Tvoje stvari. Nove prilike.','Upravljaj oglasima i prati prodaju na jednom mestu.',link(I('plus')+' Novi oglas','sell','btn'))}<div class="stat-grid">${stat('Aktivni oglasi',own.filter(l=>l.status==='ACTIVE').length,'Standardno oglašavanje je besplatno.','tag')}${stat('Pregledi oglasa',own.reduce((v,l)=>v+l.views,0),'Ukupno u testnim podacima.','eye')}${stat('Prodaje',sales.length,'Sve testne porudžbine ovog naloga.','box')}${stat('Za isplatu',D.money(sales.filter(o=>o.payoutStatus==='PENDING').reduce((v,o)=>v+o.price,0)),'Isplaćuje BEX prema potvrđenom roku.','wallet')}</div><div class="two-col"><section class="panel"><div class="row between"><h3>Tvoji oglasi</h3>${link('Premium '+I('spark'),'premium','text-btn')}</div><div class="tabs">${[['active','Aktivni'],['paused','Pauzirani'],['sold','Prodati'],['all','Svi']].map(a=>'<button class="'+(ui.sellerTab===a[0]?'active':'')+'" data-action="seller-tab" data-id="'+a[0]+'">'+a[1]+'</button>').join('')}</div>${ls.length?ls.map(l=>`<div class="seller-list"><a href="#/listing/${e(l.id)}"><img class="list-thumb" src="${e(img(l))}" alt=""></a><div class="grow"><h3><a href="#/listing/${e(l.id)}">${e(l.title)}</a></h3><div class="meta">${I('eye','icon-sm')} ${l.views} pregleda · ${e(l.city)}</div><div class="price">${D.money(l.price)}</div><div class="row wrap gap8" style="margin-top:7px">${badge(l.status)}${['ACTIVE','PAUSED'].includes(l.status)?btn(l.status==='ACTIVE'?'Pauziraj':'Aktiviraj','toggle-listing','data-id="'+e(l.id)+'"','ghost small'):''}${l.status==='ACTIVE'?btn('Izmeni','edit-listing','data-id="'+e(l.id)+'"','ghost small'):''}</div></div></div>`).join(''):empty('Ovde još nema oglasa.','Postavi svoj prvi besplatan oglas.',link('Postavi oglas','sell'))}</section><section class="stack"><div class="panel"><h3>Prodaje i isplate</h3><div class="spacer"></div>${sales.length?sales.slice().reverse().map(o=>`<div class="seller-list"><img class="list-thumb" src="${e(img(o.snapshot))}" alt=""><div class="grow"><h3>${e(o.snapshot.title)}</h3><div class="meta">${e(o.id)} · ${D.money(o.price)}</div>${badge(o.payoutStatus)}</div>${link(I('chevron'),'orders/'+o.id,'btn ghost small')}</div>`).join(''):empty('Još nema prodaja.','Kada kupac potvrdi kupovinu, pojaviće se ovde.')}</div>${alertBox('Pre prve BEX isplate neophodna je potvrda identiteta i računa koji pripada istom licu. Proveri statuse u svom profilu.','','shield')}${link('Moj profil i verifikacije '+I('arrow'),'profile','btn secondary')}</section></div>`;}
function sellView(){const d=ui.draft,step=d.step||1;return `${crumb('Postavi oglas')}${head('Neko baš to traži.','Besplatan C2C oglas. Nekoliko detalja i predmet je spreman za novi dom.',btn('Sačuvaj nacrt','save-draft','','secondary'))}<div class="checkout-layout"><section class="panel"><div class="steps">${['Predmet','Cena i dostava','Pregled i objava'].map((x,i)=>'<div class="step '+(i+1<=step?'active':'')+'"><span>'+(i+1)+'</span>'+x+'</div>').join('')}</div><form id="listing-form" data-step="${step}" class="stack"><div data-error></div>${step===1?`<div class="form-grid"><label class="field full-span">Naziv predmeta<input name="title" value="${e(d.title||'')}" required minlength="5" maxlength="100" placeholder="Npr. Sony slušalice, odlično očuvane"></label><label class="field">Kategorija<select name="category">${D.categories.filter(c=>c.id!=='all').map(c=>'<option value="'+c.id+'" '+(d.category===c.id?'selected':'')+'>'+c.name+'</option>').join('')}</select></label><label class="field">Stanje<select name="condition">${['Novo','Kao novo','Odlično','Dobro'].map(c=>'<option '+(d.condition===c?'selected':'')+'>'+c+'</option>').join('')}</select></label><label class="field full-span"><span class="row between">Opis predmeta ${btn(I('spark','icon-sm')+' Predlog opisa · demo','suggest-description','','ghost small')}</span><textarea name="description" minlength="20" required maxlength="3000" rows="5" placeholder="Opiši stanje, šta je uključeno i eventualne nedostatke.">${e(d.description||'')}</textarea></label><div class="field full-span"><span>Fotografije</span><div class="dropzone">${I('image')}<p>Dodaj jasne fotografije svog predmeta.</p><label class="btn secondary small">${I('upload')} Izaberi fotografije<input type="file" data-upload="listing" accept="image/jpeg,image/png,image/webp" multiple class="hide"></label><small>Do 5 fotografija · JPG, PNG ili WebP · do 8 MB po fotografiji</small>${btn('Ili upotrebi demo ilustraciju','demo-photo','','ghost small')}</div>${d.photos.length?'<div class="photo-list">'+d.photos.map((p,i)=>'<div class="stack gap8"><img src="'+e(photoSrc(p,{art:categoryArt(d.category)}))+'" alt="Fotografija predmeta '+(i+1)+'"><button class="text-btn small" data-action="remove-photo" data-index="'+i+'" type="button">Ukloni</button></div>').join('')+'</div>':''}<small>Detekcija kontakta u fotografijama i malware skeniranje nisu uključeni u lokalni prototip.</small></div></div>`:step===2?`<div class="form-grid"><label class="field">Cena predmeta (RSD)<input name="price" value="${d.price?e(d.price/100):''}" inputmode="decimal" required placeholder="Npr. 5500"></label><label class="field">Grad<input name="city" value="${e(d.city)}" required maxlength="60"></label><div class="field full-span"><span>Kako želiš da prodaješ?</span><label class="radio-card"><input name="mode" type="radio" value="buy" ${d.mode!=='contact'?'checked':''}><div><b>Kupi</b><p>Kupac prihvata cenu i odmah potvrđuje kupovinu pouzećem.</p></div></label><label class="radio-card"><input name="mode" type="radio" value="contact" ${d.mode==='contact'?'checked':''}><div><b>Kontaktiraj me</b><p>Dogovor kroz chat, formalna ponuda, pa kupovina pouzećem.</p></div></label></div><label class="field">Masa paketa (kg)<input name="weight" type="number" min="0.1" step="0.1" max="${S.config.maxKg}" value="${e(d.weight)}" required></label><label class="field">Dužina paketa (cm)<input name="length" type="number" min="1" max="${S.config.maxCm}" value="${e(d.dims[0])}" required></label><label class="field">Širina paketa (cm)<input name="width" type="number" min="1" max="${S.config.maxCm}" value="${e(d.dims[1])}" required></label><label class="field">Visina paketa (cm)<input name="height" type="number" min="1" max="${S.config.maxCm}" value="${e(d.dims[2])}" required></label></div>${alertBox('Jedan predmet po C2C oglasu. Isključivo BEX dostava. Nisu dostupni lično preuzimanje i online plaćanje.','','truck')}`:`<div class="checkout-product"><img src="${e(img({...d,art:categoryArt(d.category)}))}" alt=""><div><h3>${e(d.title)}</h3><p class="small muted">${e(d.city)} · ${e(d.condition)}</p><strong>${D.money(d.price)}</strong></div></div><p class="small muted">${e(d.description)}</p><div class="detail-attrs"><div><span>Prodaja</span><b>${d.mode==='buy'?'Kupi':'Kontaktiraj me'}</b></div><div><span>Dostava</span><b>BEX</b></div><div><span>Masa</span><b>${d.weight} kg</b></div><div><span>Oglas</span><b>Besplatan</b></div></div>${alertBox(D.needsProof(S,d)?'Za ovaj predmet pre predaje BEX-u obavezan je dokaz pakovanja.':'Fotografije pakovanja su preporučene.','','image')}<label class="checkline"><input type="checkbox" name="ownership" required><span>Potvrđujem da imam pravo prodaje, da je opis tačan i da ću predmet poslati isključivo BEX-om.</span></label>`}<div class="form-actions">${step>1?btn(I('back')+' Nazad','listing-back','','secondary'):'<span class="small muted">'+I('shield','icon-sm')+' Tvoj broj telefona nije javan.</span>'}<button type="submit" class="btn">${step===3?'Objavi besplatan oglas':'Sledeći korak'} ${I('arrow')}</button></div></form></section><aside class="panel stack summary-card"><h3>Mali detalji. Bolji oglas.</h3><div class="help-grid" style="grid-template-columns:1fr"><div><h4>01 · Neka se predmet vidi.</h4><p>Dnevno svetlo, čista pozadina i više uglova. Prikaži i oštećenja.</p></div><div><h4>02 · Opiši iskreno.</h4><p>Napiši šta je uključeno, koliko je korišćeno i da li sve radi.</p></div><div><h4>03 · Spakuj pažljivo.</h4><p>Unesi masu i dimenzije upakovanog predmeta. Za osetljive predmete sačuvaj dokaz pakovanja.</p></div></div>${alertBox('Standardni oglas je besplatan. Promocija je opciona i testira se zasebno.','','tag')}</aside></div>`;}
function categoryArt(c){return ({tech:'headphones',fashion:'sneaker',home:'lamp',sport:'weights',kids:'bike',books:'books',tools:'drill'})[c]||'box';}
function messagesView(){const cs=S.conversations,c=cs.find(c=>c.id===ui.chat)||cs[0];if(!c)return head('Tvoje poruke.','Dogovor ostaje na jednom mestu.')+empty('Započni razgovor.','Otvori oglas i pitaj prodavca.',link('Istraži oglase','market'));ui.chat=c.id;const l=S.listings.find(l=>l.id===c.listingId),seller=S.users[c.seller]||S.users.me;const mine=S.session.role==='seller'?c.seller:c.buyer;return `${crumb('Poruke')}${head('Dobar dogovor počinje razgovorom.','Sve poruke i formalne ponude ostaju u eBex-u.',btn('Testna uloga: '+(S.session.role==='seller'?'prodavac':'kupac'),'chat-role','','secondary'))}<div class="chat-layout"><aside class="conversation-list"><h3>Poruke <span class="muted">(${cs.length})</span></h3>${cs.map(x=>{const p=S.listings.find(l=>l.id===x.listingId);return '<button class="conversation '+(x.id===c.id?'active':'')+'" data-action="open-chat" data-id="'+e(x.id)+'"><img src="'+e(img(p||{}))+'" alt=""><span class="grow"><h4>'+e(p?.title||'Oglas')+'</h4><p>'+e(x.messages[x.messages.length-1]?.text||'Započni dogovor')+'</p></span></button>';}).join('')}</aside><section class="chat-main"><div class="chat-head"><span class="avatar sage">${e(seller.initials)}</span><div class="grow"><h3>${e(seller.name)} ${I('checkCircle','icon-sm text-green')}</h3><p><a href="#/listing/${e(l?.id)}">${e(l?.title)} · ${D.money(l?.price||0)}</a></p></div>${btn('Predloži cenu','offer','data-id="'+e(c.id)+'"','secondary small')}${btn(I('flag'),'report-chat','data-id="'+e(c.id)+'"','ghost small')}</div><div class="chat-safety">${I('shield')} Bez razmene kontakta i ličnog preuzimanja. Plaćaš BEX-u pri uručenju.</div><div class="chat-messages" id="chat-scroll">${c.messages.map(m=>'<div class="message '+(m.from===mine?'mine':'')+'"><div class="bubble">'+e(m.text)+'</div><div class="meta">'+(m.from===mine?'Ti':e(seller.name))+' · '+stamp(m.at)+'</div></div>').join('')}${c.offers.map(f=>`<div class="offer-card"><div class="row between"><span class="eyebrow">Formalna ponuda · ${f.from==='seller'?'prodavac':'kupac'}</span>${badge(new Date(f.expiresAt)<new Date(Date.now()+S.clock)&&f.status==='PENDING'?'EXPIRED':f.status)}</div><div class="price">${D.money(f.price)}</div><p class="small muted">Važi do ${stamp(f.expiresAt)} · BEX dostava se dodaje na iznos.</p>${f.status==='PENDING'?btn(f.from===(S.session.role==='seller'?'seller':'buyer')?'Promeni ulogu da prihvatiš':'Prihvati ponudu','accept-offer','data-conv="'+e(c.id)+'" data-id="'+e(f.id)+'"','secondary small'):''}${f.status==='ACCEPTED'&&l?.status==='ACTIVE'?btn('Nastavi na kupovinu pouzećem '+I('arrow'),'offer-checkout','data-conv="'+e(c.id)+'" data-id="'+e(f.id)+'"','small'):''}</div>`).join('')}</div><div id="chat-error"></div><form id="message-form" class="chat-input" data-id="${e(c.id)}"><input name="message" maxlength="1500" placeholder="${c.blocked?'Razgovor je blokiran':'Napiši poruku…'}" aria-label="Nova poruka" required ${c.blocked?'disabled':''}><button class="btn" type="submit" ${c.blocked?'disabled':''} aria-label="Pošalji poruku">${I('send')}</button></form></section></div>`;}
function premiumView(){const own=S.listings.filter(l=>l.seller==='me'&&l.status==='ACTIVE');return `${crumb('Premium')}${head('Tvoj oglas, malo više u centru pažnje.','Oglasi su besplatni. Isticanje biraš kada ti odgovara.')}<div class="tagline orange">${I('spark')}<span>Cene i trajanja ispod su testni parametri. Aktiviranje promocije ne naplaćuje novac.</span></div><div class="spacer"></div><div class="three-col">${S.config.plans.map((p,i)=>`<article class="plan ${i===1?'featured':''}"><div class="row between"><h3>${e(p.name)}</h3>${I(i===2?'spark':i===1?'star':'arrow','text-coral')}</div><p>${e(p.description)}</p><div class="price">${fmt(p.price)} <small>RSD</small></div><small class="muted">${p.days} dana · testna cena</small><ul><li>${I('check')}${i===0?'Povratak među najnovije':'Jasna premium oznaka'}</li><li>${I('check')}Više pažnje u ${i===2?'preporukama':'kategoriji'}</li><li>${I('check')}Bez automatske obnove</li></ul>${btn('Isprobaj '+e(p.name),'promote','data-id="'+e(p.id)+'"',i===1?'':'secondary')}</article>`).join('')}</div><div class="spacer"></div><section class="panel"><h3>Tvoji aktivni oglasi</h3>${own.length?own.map(l=>'<div class="seller-list"><img class="list-thumb" src="'+e(img(l))+'" alt=""><div class="grow"><h3>'+e(l.title)+'</h3><div class="meta">'+D.money(l.price)+'</div></div>'+(D.effectivePremium(l,S)?'<span class="badge orange">Promocija do '+date(l.premiumUntil)+'</span>':'<span class="badge gray">Standardni oglas</span>')+'</div>').join(''):empty('Prvo postavi oglas.','Onda možeš da isprobaš promociju.',link('Postavi oglas','sell'))}</section>`;}
function profileView(){const u=S.users.me;return `${crumb('Moj profil')}${head('Tvoj eBex nalog.','Verifikacije, poverenje i podešavanja privatnosti.')}<div class="two-col"><section class="panel"><div class="profile-header"><span class="avatar">${e(u.initials)}</span><div><h2>${e(u.name)}</h2><p class="small muted">${e(u.city)} · član od ${u.since}. · ★ ${u.rating}</p></div><span class="badge gray">Test nalog</span></div><form id="profile-form" class="stack"><div data-error></div><label class="field">Ime i prezime<input name="name" value="${e(u.name)}" minlength="3" required maxlength="70"></label><label class="field">Grad<input name="city" value="${e(u.city)}" required maxlength="60"></label><label class="field">O tebi<textarea name="bio" maxlength="300">${e(u.bio||'')}</textarea></label><button class="btn secondary" type="submit">Sačuvaj profil</button></form></section><section class="panel"><h3>Odvojeni statusi verifikacije</h3>${[['phone','Telefon','SMS provera je simulirana.','user'],['email','E-mail','Testni dodatni kanal.','bell'],['identity','Identitet','Bez stvarne KYC provere.','shield'],['bank','Račun za isplatu','Mora pripadati istom licu.','wallet']].map(a=>`<div class="verification"><div class="row">${I(a[3],'text-green')}<div><h4>${a[1]}</h4><p>${a[2]}</p></div></div>${btn(u[a[0]]?'Potvrđeno · izmeni':'Potvrdi','verify','data-id="'+a[0]+'"',(u[a[0]]?'soft':'secondary')+' small')}</div>`).join('')}${alertBox('Za test registracije ukloni potvrdu telefona, pa unesi demo SMS kod <b>123456</b>. Nikakva poruka se ne šalje.','orange','info')}<div class="spacer"></div>${btn('Testiraj račun drugog lica','foreign-bank','','secondary small')}</section><section class="panel stack"><h3>Privatnost i podaci</h3><p class="small muted">Podaci se čuvaju u ovom pregledaču. Koristi isključivo izmišljene podatke i testne fotografije.</p><div class="row wrap">${btn(I('download')+' Izvezi testne podatke','export','','secondary small')}${btn('Zahtev za brisanje','data-request','','secondary small')}</div>${S.dataRequests.length?'<p class="small muted">'+S.dataRequests.length+' testnih zahteva je evidentirano za pregled.</p>':''}</section><section class="panel stack"><h3>Sačuvane pretrage</h3>${S.savedSearches.length?S.savedSearches.map((q,i)=>'<div class="mini-list"><span>'+e(q.query||D.categories.find(c=>c.id===q.category)?.name||'Svi oglasi')+'</span>'+btn('Otvori','load-search','data-index="'+i+'"','ghost small')+'</div>').join(''):'<p class="small muted">Sačuvaj pretragu sa početne strane.</p>'}</section></div>`;}

function adminView(tab='overview'){
 if(S.session.role!=='admin')return `${crumb('Administracija')}${head('Operativni centar eBex.','Moderacija, porudžbine, reklamacije i finansijsko usaglašavanje.')}<div class="panel stack" style="max-width:660px;margin:40px auto"><h2>Ulazak u testnu administraciju</h2><p class="muted">Testiraj različita ovlašćenja i odluke na sintetičkim podacima. U prototipu je promena uloge slobodna; prava autentikacija i MFA dolaze u produkcionoj fazi.</p>${btn(I('sliders')+' Otvori testni administratorski nalog','admin-login','','large')}${alertBox('Ovo je lokalni prototip. RBAC prikazuje princip rada, a ne produkcionu zaštitu.','orange','lock')}</div>`;
 const tabs=[['overview','Pregled','chart'],['users','Korisnici','user'],['listings','Moderacija','shield'],['orders','Porudžbine','box'],['disputes','Reklamacije i povrati','flag'],['finance','COD i isplate','wallet'],['shipping','BEX pošiljke','truck'],['premium','Premium katalog','spark'],['config','Poslovna pravila','settings'],['audit','Revizijski trag','eye']];
 const roles={super:'Super administrator',finance:'Finansije i usaglašavanje',moderator:'Moderator',support:'Podrška i sporovi',auditor:'Revizor · samo čitanje'};
 let body='';const delivered=S.orders.filter(o=>o.codStatus==='COLLECTED'),paid=S.orders.filter(o=>o.payoutStatus==='PAID');
 if(tab==='overview')body=`<div class="stat-grid">${stat('Aktivni oglasi',S.listings.filter(l=>l.status==='ACTIVE').length,'Trenutno stanje demo kataloga.','tag')}${stat('Porudžbine',S.orders.length,'Ukupan broj testnih transakcija.','box')}${stat('Naplaćeno pouzeće',D.money(S.ledger.filter(l=>l.type==='COD').reduce((a,l)=>a+l.amount,0)),'Iznos BEX simuliranih COD događaja.','wallet')}${stat('Reklamacije',S.orders.filter(o=>o.dispute&&o.dispute.status!=='RESOLVED').length,'Otvoreni testni slučajevi.','flag')}</div><div class="two-col"><div class="panel stack"><h3>Oglasi po kategorijama</h3><p class="small muted">Stvarni broj zapisa u lokalnom demo katalogu.</p>${D.categories.filter(c=>c.id!=='all').map(c=>{const n=S.listings.filter(l=>l.category===c.id&&l.status==='ACTIVE').length;return '<div class="stack gap8"><div class="row between small"><span>'+c.name+'</span><b>'+n+'</b></div><div class="progress"><i style="width:'+Math.min(100,n/Math.max(1,S.listings.filter(l=>l.status==='ACTIVE').length)*100)+'%"></i></div></div>';}).join('')}</div><div class="panel stack"><h3>Tok transakcija</h3>${[['Porudžbine',S.orders.length],['BEX preuzimanje',S.orders.filter(o=>['IN_TRANSIT','DELIVERED'].includes(o.shipmentStatus)).length],['Uručeno i COD naplaćeno',delivered.length],['Isplata potvrđena',paid.length],['Otvoreni sporovi',S.orders.filter(o=>o.dispute).length]].map(a=>'<div class="mini-list"><span>'+a[0]+'</span><b>'+a[1]+'</b></div>').join('')}${alertBox('Produkcioni BEX API, pravni model C2C isplate i pravovremeno zadržavanje isplate zahtevaju potvrdu pre produkcije.','orange','lock')}</div></div>`;
 else if(tab==='users')body=`<div class="panel flush"><div class="panel-head"><h3>Korisnici i odvojene verifikacije</h3><p class="small muted">Svi prikazani nalozi su sintetički.</p></div><div class="table-wrap"><table><thead><tr><th>Korisnik</th><th>Telefon</th><th>Identitet</th><th>Račun</th><th>Reputacija</th></tr></thead><tbody>${Object.values(S.users).map(u=>'<tr><td><span class="avatar sage">'+e(u.initials)+'</span> '+e(u.name)+'</td><td>'+badge(u.phone?'ACTIVE':'PENDING')+'</td><td>'+badge(u.identity?'ACTIVE':'PENDING')+'</td><td>'+badge(u.bank?'ACTIVE':'PENDING')+'</td><td>★ '+u.rating+' · '+u.trades+' transakcija</td></tr>').join('')}</tbody></table></div></div>`;
 else if(tab==='listings')body=`<div class="panel flush"><div class="panel-head"><h3>Pregled i moderacija oglasa</h3><p class="small muted">Tekstualna pravila su aktivna. OCR fotografija i AI moderacija nisu povezani.</p></div><div class="table-wrap"><table><thead><tr><th>Oglas</th><th>Status i razlog</th><th>Prodavac</th><th>Radnja</th></tr></thead><tbody>${S.listings.map(l=>'<tr><td><a class="table-title" href="#/listing/'+e(l.id)+'">'+e(l.title)+'</a><div class="table-sub">'+D.money(l.price)+'</div></td><td>'+badge(l.status)+(l.status==='PENDING_REVIEW'?'<p class="table-sub">'+e(S.moderation.find(m=>m.listingId===l.id)?.reason||'Potreban pregled')+'</p>':'')+'</td><td>'+e(S.users[l.seller]?.name)+'</td><td>'+(l.status==='PENDING_REVIEW'?btn('Odobri','moderate','data-id="'+e(l.id)+'" data-decision="approve"','secondary small')+' ':'')+(['ACTIVE','PENDING_REVIEW'].includes(l.status)?btn('Ukloni','moderate','data-id="'+e(l.id)+'" data-decision="remove"','ghost small'):'—')+'</td></tr>').join('')}</tbody></table></div></div>`;
 else if(tab==='orders')body=adminOrders(S.orders);
 else if(tab==='disputes'){const os=S.orders.filter(o=>o.dispute);body=`<div class="stack">${alertBox('Odluke zahtevaju obrazloženje. Ukidanje zadržavanja i COD povraćaj dozvoljeni su samo finansijama ili super administratoru.','blue','shield')}${os.length?os.map(o=>orderCard(o)).join(''):empty('Nema otvorenih reklamacija.','Otvori problem na testnoj porudžbini ili pokreni scenario.',link('Otvori Test centar','test'))}</div>`;}
 else if(tab==='shipping')body=`<div class="panel flush"><div class="panel-head"><div class="row between"><h3>BEX pošiljke · simulator</h3><span class="badge orange">Nema mrežnih API poziva</span></div></div><div class="table-wrap"><table><thead><tr><th>Pošiljka / porudžbina</th><th>Logistika</th><th>Pouzeće</th><th>Dokaz</th><th>Detalji</th></tr></thead><tbody>${S.orders.slice().reverse().map(o=>'<tr><td><b>'+e(o.id)+'</b><div class="table-sub monospace">'+e(o.shipment)+'</div></td><td>'+badge(o.shipmentStatus)+'</td><td>'+D.money(o.total)+'<div class="table-sub">'+e(label(o.codStatus))+'</div></td><td>'+(o.evidence.length?'Evidentiran':o.proofRequired?'Nedostaje':'Preporučen')+'</td><td>'+link('Prati','orders/'+o.id,'btn secondary small')+'</td></tr>').join('')}</tbody></table></div></div>`;
 else if(tab==='finance')body=`<div class="stat-grid">${stat('COD naplata',D.money(S.ledger.filter(x=>x.type==='COD').reduce((a,x)=>a+x.amount,0)),'Simulirani BEX izvor.','wallet')}${stat('Isplate prodavcima',D.money(S.ledger.filter(x=>x.type==='PAYOUT').reduce((a,x)=>a+x.amount,0)),'Samo potvrđeni testni događaji.','checkCircle')}${stat('Zadržane isplate',S.orders.filter(o=>o.payoutStatus.includes('HOLD')).length,'Reklamacija / provera rizika.','lock')}${stat('COD povraćaji',D.money(S.ledger.filter(x=>x.type==='REFUND').reduce((a,x)=>a+x.amount,0)),'Uz potvrđen BEX povrat.','refresh')}</div><div class="panel stack"><div class="row between wrap"><h3>Usaglašavanje sa demo BEX izvodom</h3>${btn('Generiši demo izvod','statement','','secondary small')}</div><p class="small muted">Demo izvod se pravi iz trenutnih COD podataka. Zasebna komanda dodaje razliku od 100 RSD da proveriš prikaz neslaganja.</p>${S.statement?'<div class="table-wrap"><table><thead><tr><th>Porudžbina</th><th>eBex COD</th><th>Demo BEX izvod</th><th>Razlika</th></tr></thead><tbody>'+S.statement.map(x=>{const expected=S.ledger.filter(l=>l.orderId===x.orderId&&l.type==='COD').reduce((a,l)=>a+l.amount,0);return '<tr><td>'+e(x.orderId)+'</td><td>'+D.money(expected)+'</td><td>'+D.money(x.amount)+'</td><td><span class="badge '+(x.amount!==expected?'red':'green')+'">'+D.money(x.amount-expected)+'</span></td></tr>';}).join('')+'</tbody></table></div><div class="row wrap">'+btn('Dodaj testno neslaganje','statement-mismatch','','secondary small')+btn('Evidentiraj proveru','reconcile','','secondary small')+'</div>':''}</div><div class="spacer"></div><div class="panel flush"><div class="panel-head row between"><div><h3>Finansijska evidencija</h3><p class="small muted">Par dugovne i potražne strane po događaju · nepromenljivi zapisi u aplikaciji.</p></div>${btn(I('download')+' CSV','export-ledger','','secondary small')}</div><div class="table-wrap"><table><thead><tr><th>Vreme</th><th>Porudžbina / tip</th><th>Iznos</th><th>Dugovna strana</th><th>Potražna strana / referenca</th></tr></thead><tbody>${S.ledger.map(x=>'<tr><td>'+stamp(x.at)+'</td><td>'+e(x.orderId)+'<div class="table-sub">'+e(x.type)+'</div></td><td class="nowrap">'+D.money(x.amount)+'</td><td>'+e(x.debit)+'</td><td>'+e(x.credit)+'<div class="table-sub monospace">'+e(x.ref)+'</div></td></tr>').join('')}</tbody></table></div></div>`;
 else if(tab==='config')body=`<form id="config-form" class="panel stack"><div data-error></div><h3>Podesiva testna pravila</h3>${alertBox('Sve vrednosti su razvojne pretpostavke, ne potvrđene BEX tarife ili ugovorni rokovi. Menja ih super administrator.','orange','settings')}<div class="form-grid">${[['shippingBase','Osnovna BEX dostava (RSD)',S.config.shippingBase/100,0,100000,.01],['shippingPerKg','Dodatni kg (RSD)',S.config.shippingPerKg/100,0,100000,.01],['shopDiscount','Umanjenje za Paket Shop (RSD)',S.config.shopDiscount/100,0,100000,.01],['proofThreshold','Prag obaveznog dokaza (RSD)',S.config.proofThreshold/100,1,10000000,.01],['maxKg','Maksimalna masa (kg)',S.config.maxKg,.1,100,.1],['maxCm','Maksimalna stranica (cm)',S.config.maxCm,1,300,1],['dispatchHours','Rok predaje (sati)',S.config.dispatchHours,1,720,1],['payoutDays','Testni rok isplate (dani)',S.config.payoutDays,1,30,1]].map(a=>'<label class="field">'+a[1]+'<input type="number" name="'+a[0]+'" value="'+a[2]+'" min="'+a[3]+'" max="'+a[4]+'" step="'+a[5]+'" required></label>').join('')}</div><label class="checkline"><input name="holdSupported" type="checkbox" ${S.config.holdSupported?'checked':''}><span>Simulator podržava BEX potvrdu zadržavanja i ukidanja zadržavanja isplate.</span></label><p class="small muted">Elektronika zahteva dokaz pakovanja i ispod praga. Produkcioni rokovi, praznici i cut-off nisu implementirani u ovoj simulaciji.</p><button class="btn" type="submit" ${S.session.adminRole!=='super'?'disabled':''}>Sačuvaj testna pravila</button><div class="contract-list"><div>${I('lock')} Zaključano: Srbija · C2C · RSD · samo BEX · samo pouzeće.</div><div>${I('lock')} Besplatni standardni oglasi · bez obavezne provizije.</div><div>${I('lock')} Bez automobila, nekretnina, B2C i B2B u početnom obimu.</div></div></form>`;
 else if(tab==='premium')body=`<form id="plans-form" class="panel stack"><div data-error></div><h3>Premium katalog · testna konfiguracija</h3><p class="small muted">Nazivi, testne cene i trajanja mogu da se promene. Aktivacije ne naplaćuju novac.</p>${S.config.plans.map(p=>'<div class="form-section"><div class="form-grid"><label class="field">Naziv<input name="'+p.id+'_name" value="'+e(p.name)+'" required maxlength="35"></label><label class="field">Cena (RSD)<input type="number" name="'+p.id+'_price" value="'+p.price/100+'" required min="0" step="0.01"></label><label class="field">Trajanje (dani)<input type="number" name="'+p.id+'_days" value="'+p.days+'" required min="1" max="365"></label><label class="field">Opis<input name="'+p.id+'_description" value="'+e(p.description)+'" required maxlength="100"></label></div></div>').join('')}<button type="submit" class="btn" ${S.session.adminRole!=='super'?'disabled':''}>Sačuvaj katalog</button></form>`;
 else if(tab==='audit')body=`<section class="panel stack"><div class="row between"><h3>Revizijski trag</h3>${btn(I('download')+' Izvezi CSV','export-audit','','secondary small')}</div><input type="search" id="audit-search" placeholder="Filtriraj po radnji, referenci ili opisu…" aria-label="Pretraga revizijskog traga"><div id="audit-rows">${auditRows('')}</div><p class="small muted">Zapisi se dodaju bez izmene postojećih kroz UI. Lokalni podaci mogu se menjati van aplikacije; ovo nije produkciono nepromenljivo skladište.</p></section>`;
 else body=empty('Izaberi sekciju administracije.','Koristi navigaciju na levoj strani.');
 return `${crumb('Administracija')}<div class="admin-header">${I('sliders')}<div><h3>eBex operativni centar</h3><p>Testni administratorski portal · sve integracije su simulirane.</p></div><select data-change="admin-role" aria-label="Administratorska uloga">${Object.entries(roles).map(a=>'<option value="'+a[0]+'" '+(S.session.adminRole===a[0]?'selected':'')+'>'+a[1]+'</option>').join('')}</select></div><div class="sidebar-layout"><aside class="sidenav">${tabs.map(a=>'<a href="#/admin/'+a[0]+'" class="'+(tab===a[0]?'active':'')+'">'+I(a[2])+a[1]+'</a>').join('')}</aside><div><div class="page-head"><div><h2>${tabs.find(t=>t[0]===tab)?.[1]||'Administracija'}</h2><p>Ovlašćenja: ${e(roles[S.session.adminRole])}</p></div></div>${body}</div></div>`;
}
function adminOrders(os){return '<section class="panel flush"><div class="panel-head"><h3>Sve testne porudžbine</h3></div><div class="table-wrap"><table><thead><tr><th>Porudžbina</th><th>Ukupno pouzeće</th><th>Prodavac</th><th>Status</th><th></th></tr></thead><tbody>'+os.slice().reverse().map(o=>'<tr><td><b>'+e(o.id)+'</b><div class="table-sub">'+e(o.snapshot.title)+'</div></td><td>'+D.money(o.total)+'</td><td>'+e(S.users[o.seller]?.name)+'</td><td>'+badge(o.status)+'</td><td>'+link('Otvori','orders/'+o.id,'btn secondary small')+'</td></tr>').join('')+'</tbody></table></div></section>';}
function auditRows(query){return S.audit.filter(a=>D.normalized(a.action+' '+a.detail+' '+a.ref+' '+a.actor).includes(D.normalized(query))).slice(0,150).map(a=>'<div class="audit-entry"><span class="muted">'+stamp(a.at)+'<br>'+e(a.actor)+'</span><span><b>'+e(a.action)+'</b><br><span class="monospace muted">'+e(a.ref)+'</span></span><span>'+e(a.detail)+'</span></div>').join('')||'<p class="small muted">Nema rezultata.</p>';}
function testView(){return `${crumb('Test centar')}${head('Isprobaj ceo krug.','Svaki scenario pravi zasebnu testnu porudžbinu. Nema pravih pošiljaka i plaćanja.',btn(I('download')+' Izvezi stanje','export','','secondary'))}<div class="two-col"><section class="stack">${[['success','Uspešna kupovina','Potvrdi kupovinu, dodaj dokaz, predaj BEX-u, simuliraj uručenje i isplatu.'],['hold','Reklamacija pre isplate','Uručen predmet sa otvorenom reklamacijom. Isplata mora ostati zaustavljena.'],['after','Reklamacija nakon isplate','Isplata je već izvršena. Prijava pokreće pregled, bez lažnog zamrzavanja novca.'],['proof','Obavezan dokaz pakovanja','Vredniji predmet ne može u BEX transport dok prodavac ne doda dokaz.'],['return','BEX povrat i COD povraćaj','Otvoren spor spreman za odluku administratora, BEX povrat i proveru refundacije.']].map((a,i)=>'<div class="test-scenario"><span class="num">0'+(i+1)+'</span><div class="grow"><h3>'+a[1]+'</h3><p>'+a[2]+'</p></div>'+btn('Pokreni '+I('arrow'),'scenario','data-id="'+a[0]+'"','secondary small')+'</div>').join('')}<section class="panel stack"><div class="row between wrap"><h3>Automatske provere poslovnih pravila</h3>${btn(I('play')+' Pokreni provere','run-tests','','small')}</div><p class="small muted">Testovi se izvršavaju nad zasebnim kopijama. Ne menjaju tvoje probne transakcije.</p>${ui.tests.length?'<b class="text-green">'+ui.tests.filter(t=>t.pass).length+' / '+ui.tests.length+' uspešnih provera</b>'+ui.tests.map(t=>'<div class="test-result '+(!t.pass?'fail':'')+'"><span>'+e(t.name)+'</span><b>'+ (t.pass?'✓':'✕')+'</b></div>').join(''):alertBox('Proveri duplirane događaje, redosled statusa, zadržavanje isplate, račune i povrate.','','checkCircle')}</section></section><aside class="stack"><section class="panel stack"><h3>Predloženi redosled testiranja</h3><div class="help-grid" style="grid-template-columns:1fr">${[['Kupac','Nađi oglas, sačuvaj ga i potvrdi kupovinu pouzećem. Probaj pretragu, filtere i dogovor kroz chat.'],['Prodavac','Postavi oglas u tri koraka. Unesi kontakt u opis da proveriš moderaciju. Dodaj dokaz pakovanja.'],['Administrator','Promeni ulogu, pregledaj reklamaciju i upiši obrazloženje odluke. Isprobaj moderatora bez finansijskih ovlašćenja.'],['BEX simulator','Na detalju porudžbine šalji događaje, pomeri sat za +1 dan i ponovi poslednji događaj. Prati da nema duplih unosa.']].map(a=>'<div><h4>'+a[0]+'</h4><p>'+a[1]+'</p></div>').join('')}</div><div class="row wrap">${link('Moj profil','profile','btn secondary small')}${link('Administracija','admin/overview','btn secondary small')}</div></section><section class="panel stack"><h3>Sačuvaj svoje testiranje</h3><p class="small muted">Stanje se pamti u ovom pregledaču. JSON izvoz prenosi oglase, razgovore, porudžbine, podešavanja i evidenciju. Nije zajednička baza za više uređaja.</p><div class="row wrap">${btn('Izvezi JSON','export','','secondary small')}<label class="btn secondary small">Uvezi JSON<input type="file" data-upload="import" accept="application/json,.json" class="hide"></label>${btn('Vrati početne podatke','reset','','ghost small')}</div><p class="small muted">Izvoz čuva i testne fotografije. Koristi samo izmišljene podatke.</p></section><section class="panel stack"><h3>Obim ovog prototipa</h3><p class="small muted">Funkcionalni HTML prototip za web i mobilni pregledač. Lokalna memorija, simulirani SMS, KYC, BEX dostava, pouzeće i isplata.</p><p class="small muted">Nisu uključeni stvarna baza, server i autorizacija, zasebne iOS/Android aplikacije, OCR, video dokazi, stvarni AI servisi i slanje obaveštenja.</p>${alertBox('Za produkciju su potrebni BEX ugovor i zvanična API dokumentacija, potvrda C2C isplate i hold mehanizma, KYC, pravna i bezbednosna provera.','orange','lock')}</section></aside></div><div class="section-heading"><div><h2>Sve testne porudžbine</h2><p>Otvori bilo koju porudžbinu i nastavi scenario.</p></div></div>${adminOrders(S.orders)}`;}

function render(){
 const [page='market',id]=route();let content;
 try{switch(page){case 'market':content=home();break;case 'favorites':content=home(true);break;case 'listing':content=detail(id);break;case 'checkout':content=checkoutView();break;case 'orders':content=ordersView(id);break;case 'sell':content=sellView();break;case 'seller':content=sellerView();break;case 'messages':content=messagesView();break;case 'premium':content=premiumView();break;case 'profile':content=profileView();break;case 'admin':content=adminView(id);break;case 'test':content=testView();break;default:content=empty('Stranica nije pronađena.','Vrati se na početnu.',link('Istraži oglase','market'));}}
 catch(err){content=empty('Prikaz nije mogao da se učita.',e(err.message),link('Test centar','test'));console.error(err);}
 $('#shell').innerHTML=header()+'<main id="main-content" class="app">'+(!storageOK?alertBox('Pregledač ne dozvoljava čuvanje. Test radi u memoriji; izvezi JSON pre zatvaranja.','orange','info')+'<div class="spacer"></div>':'')+content+'</main>'+footer();
 document.title='eBex · '+({market:'Nova prilika za dobre stvari',listing:'Oglas',orders:'Porudžbine',sell:'Postavi oglas',seller:'Moja prodaja',messages:'Poruke',premium:'Premium',profile:'Moj profil',admin:'Administracija',test:'Test centar',favorites:'Sačuvani oglasi',checkout:'Potvrdi kupovinu'})[page];
 const chat=$('#chat-scroll');if(chat)chat.scrollTop=chat.scrollHeight;
}
function openModal(title,sub,body,wide=false){focusBefore=document.activeElement;$('#modals').innerHTML='<div class="modal-backdrop" data-backdrop><section class="modal '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">'+title+'</h2><p>'+sub+'</p></div><button class="modal-close" data-action="close" aria-label="Zatvori">'+I('close')+'</button></div>'+body+'</section></div>';document.body.style.overflow='hidden';requestAnimationFrame(()=>$('#modals input, #modals select, #modals textarea, #modals button')?.focus());}
function closeModal(){$('#modals').innerHTML='';document.body.style.overflow='';if(focusBefore?.isConnected)focusBefore.focus();}
function help(){openModal('Dobre stvari, jednostavan dogovor.','eBex povezuje kupca, prodavca i BEX.',`<div class="help-grid"><div><h4>1. Pronađi ili postavi oglas.</h4><p>Fizička lica postavljaju standardne oglase besplatno. Izaberi „Kupi” ili „Kontaktiraj me”.</p></div><div><h4>2. Dogovor ostaje ovde.</h4><p>Za dogovornu cenu pošalji formalnu ponudu u chatu. Prihvata je druga strana.</p></div><div><h4>3. BEX donosi na vrata.</h4><p>Prodavac pažljivo pakuje predmet i prilaže dokaz kada je obavezan. Dostava je samo preko BEX-a.</p></div><div><h4>4. Plaćanje tek pri uručenju.</h4><p>BEX naplaćuje pouzeće i isplaćuje prodavca. Reklamacija pre isplate pokreće zadržavanje i pregled.</p></div></div><div class="spacer"></div>${alertBox('U testnom prototipu sve pošiljke, verifikacije i finansijski događaji su simulirani. Stanje se čuva u ovom pregledaču.','orange','play')}<div class="spacer"></div>${link('Otvori Test centar '+I('arrow'),'test','btn full')}`,true);}
function formError(form,err){const target=form?.querySelector('[data-error]');if(target){target.innerHTML='<div class="field-error" role="alert">'+I('info')+'<span>'+e(err.message||err)+'</span></div>';target.scrollIntoView({block:'nearest',behavior:'smooth'});}else toast(err.message||err,true);}
function startCheckout(id,offer){const l=S.listings.find(l=>l.id===id);if(!l||l.status!=='ACTIVE')throw Error('Oglas više nije dostupan.');ui.checkout={id,offerId:offer?.id,price:offer?.price||l.price,delivery:'home',requestId:D.uid('checkout')};if(S.session.role!=='buyer')commit(s=>s.session.role='buyer');closeModal();go('checkout');}
function rememberDraft(form=$('#listing-form')){if(!form)return;const f=Object.fromEntries(new FormData(form));const step=Number(form.dataset.step);if(step===1)Object.assign(ui.draft,{title:f.title||'',description:f.description||'',category:f.category,condition:f.condition});if(step===2)Object.assign(ui.draft,{price:amount(f.price),city:f.city,mode:f.mode,weight:Number(f.weight),dims:[Number(f.length),Number(f.width),Number(f.height)]});}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"').join(';')).join('\r\n');}
async function readPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Dozvoljene su JPG, PNG i WebP fotografije.');if(file.size>8*1024*1024)throw Error('Fotografija mora biti manja od 8 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Fotografija nije mogla da se učita.'));r.readAsDataURL(file);});const image=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Datoteka nije ispravna fotografija.'));image.src=data;});const max=900,scale=Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);return {name:file.name,data:canvas.toDataURL('image/jpeg',.76),size:file.size};}
function scenario(kind){let id;commit(s=>{const l=D.clone(s.listings.find(l=>l.id==='l1'));l.id=D.uid('scenario');l.title=({success:'Demo · Uspešna kupovina',hold:'Demo · Reklamacija pre isplate',after:'Demo · Prijava nakon isplate',proof:'Demo · Obavezan dokaz pakovanja',return:'Demo · Povrat i COD refundacija'})[kind];l.status='ACTIVE';l.seller='s1';s.listings.push(l);s.session.role='buyer';const o=D.createOrder(s,{listingId:l.id,address:{name:'Test Kupac',street:'Test adresa 1',city:'Beograd',postal:'11000'},requestId:D.uid('scenario')});id=o.id;if(['hold','after','return'].includes(kind)){o.evidence.push({name:'Demo dokaz pakovanja',demo:true,at:D.now()});D.simulate(s,id,'DELIVERED');if(kind==='after'){s.clock+=2*864e5;D.simulate(s,id,'PAYOUT');}D.complain(s,id,'Stanje odstupa od opisa','Testna reklamacija radi provere postupka i finansijskih pravila.');}D.audit(s,'DEMO','SCENARIO_CREATED',kind,id);});go('orders/'+id);toast('Kreiran je zaseban testni scenario.');}

document.addEventListener('click',ev=>{
 const target=ev.target.closest('[data-action]');if(!target){if(ev.target.matches('[data-backdrop]'))closeModal();if(ev.target.closest('#modals a'))closeModal();return;}
 ev.preventDefault();const a=target.dataset.action,id=target.dataset.id;
 try{switch(a){
 case 'close':closeModal();break;
 case 'help':help();break;
 case 'privacy':openModal('Tvoji podaci u testnom prototipu.','Nema slanja na BEX, SMS ili KYC servise.','<div class="stack"><p class="muted">Podaci su lokalni u pregledaču i nisu šifrovani. Ne unosi stvarne lične, bankarske ili poverljive podatke. JSON izvoz sadrži testne razgovore, evidenciju i fotografije.</p><p class="muted">Ovo objašnjenje nije produkciona politika privatnosti. Stvarna politika i rokovi čuvanja zahtevaju pravno odobrenje.</p>'+link('Profil i podaci','profile')+'</div>');break;
 case 'account':{const prev=$('.menu-pop');if(prev){prev.remove();break;}const menu=document.createElement('div');menu.className='menu-pop';menu.innerHTML='<div class="role-label">Testna uloga</div>'+[['buyer','Kupac','user'],['seller','Prodavac','tag'],['admin','Administrator','sliders']].map(r=>'<button data-action="role" data-id="'+r[0]+'">'+I(r[2])+r[1]+(S.session.role===r[0]?' ✓':'')+'</button>').join('')+'<hr><button data-action="profile">'+I('user')+'Moj profil i verifikacije</button><button data-action="test-page">'+I('play')+'Test centar</button>';$('.header').append(menu);break;}
 case 'role':setRole(id,id==='admin'?'admin/overview':id==='seller'?'seller':'market');toast('Testna uloga: '+({buyer:'kupac',seller:'prodavac',admin:'administrator'})[id]);break;
 case 'role-for-order':setRole(target.dataset.role,'orders/'+id);break;
 case 'profile':go('profile');break;case 'test-page':go('test');break;
 case 'notifications':{const notes=D.clone(S.notifications);commit(s=>s.notifications.forEach(n=>n.read=true));openModal('Tvoja obaveštenja.','Testni događaji i novosti u aplikaciji.',notes.length?notes.map(n=>'<div class="notification-item">'+I('bell')+'<div class="grow"><div class="title">'+e(n.title)+'</div><p>'+e(n.text)+'</p><div class="tiny muted">'+stamp(n.at)+'</div>'+(n.kind==='order'?link('Otvori porudžbinu','orders/'+n.ref,'text-btn'):'')+'</div></div>').join(''):empty('Sve je mirno.','Nova obaveštenja pojaviće se ovde.'));render();break;}
 case 'favorite':commit(s=>{const i=s.favorites.indexOf(id);if(i>=0)s.favorites.splice(i,1);else s.favorites.push(id);});render();break;
 case 'category':ui.category=id;ui.limit=8;go(route()[0]==='favorites'?'favorites':'market');render();break;
 case 'all-categories':ui.filters=true;ui.category='all';render();$('.category-strip')?.scrollIntoView({behavior:'smooth',block:'center'});break;
 case 'filters':ui.filters=!ui.filters;render();break;
 case 'verified':ui.onlyVerified=!ui.onlyVerified;render();break;
 case 'premium-filter':ui.onlyPremium=!ui.onlyPremium;render();break;
 case 'clear-filters':Object.assign(ui,{category:'all',query:'',condition:'',city:'',mode:'',min:'',max:'',onlyPremium:false,onlyVerified:false,limit:8});render();break;
 case 'load-more':ui.limit+=8;render();break;
 case 'save-search':{const search={query:ui.query,category:ui.category,condition:ui.condition,city:ui.city,mode:ui.mode,min:ui.min,max:ui.max};commit(s=>{if(!s.savedSearches.some(x=>JSON.stringify(x)===JSON.stringify(search)))s.savedSearches.push(search);});toast('Pretraga je sačuvana u tvom profilu.');break;}
 case 'load-search':Object.assign(ui,S.savedSearches[Number(target.dataset.index)]);go('market');break;
 case 'photo':{const l=S.listings.find(l=>l.id===id);ui.listingPhoto=l.photos.length?photoSrc(l.photos[Number(target.dataset.index)],l):img(l);$('#detail-main-image').src=ui.listingPhoto;$$('.thumbs button').forEach(b=>b.classList.toggle('active',b===target));break;}
 case 'checkout':startCheckout(id);break;
 case 'contact':{let cid;commit(s=>{let c=s.conversations.find(c=>c.listingId===id);if(!c){const l=s.listings.find(l=>l.id===id);if(l.seller==='me')throw Error('Ne možeš kontaktirati sebe.');c={id:D.uid('chat'),listingId:id,buyer:'me',seller:l.seller,messages:[{id:D.uid('msg'),from:l.seller,text:'Zdravo! Ovo je demo razgovor. Promenom testne uloge možeš da isprobaš obe strane.',at:D.now()}],offers:[],unread:0};s.conversations.push(c);}cid=c.id;});ui.chat=cid;go('messages');break;}
 case 'open-chat':ui.chat=id;commit(s=>{s.conversations.find(c=>c.id===id).unread=0;});render();break;
 case 'chat-role':setRole(S.session.role==='seller'?'buyer':'seller','messages');break;
 case 'offer':openModal('Predloži cenu.','Formalna ponuda važi 24 sata po testnom satu.',`<form id="offer-form" data-id="${e(id)}" class="stack"><div data-error></div><label class="field">Cena predmeta (RSD)<input name="price" inputmode="decimal" placeholder="Unesi iznos" required></label><p class="small muted">BEX dostava se dodaje pri kupovini. Ponudu prihvata druga strana.</p><button class="btn" type="submit">Pošalji testnu ponudu</button></form>`);break;
 case 'accept-offer':commit(s=>D.acceptOffer(s,target.dataset.conv,id));render();toast('Ponuda prihvaćena. Sada možeš na kupovinu pouzećem.');break;
 case 'offer-checkout':{const c=S.conversations.find(c=>c.id===target.dataset.conv),f=c.offers.find(f=>f.id===id);startCheckout(c.listingId,f);break;}
 case 'report-chat':openModal('Prijavi razgovor.','Prijava odlazi u testni revizijski trag.',`<form id="report-form" data-ref="${e(id)}" data-kind="chat" class="stack"><div data-error></div><label class="field">Razlog<textarea name="reason" minlength="10" required placeholder="Opiši problem…"></textarea></label><label class="checkline"><input type="checkbox" name="block">Blokiraj dalje poruke u ovom razgovoru.</label><button class="btn" type="submit">Evidentiraj prijavu</button></form>`);break;
 case 'report-listing':openModal('Prijavi oglas.','Administrator pregleda testnu prijavu.',`<form id="report-form" data-ref="${e(id)}" data-kind="listing" class="stack"><div data-error></div><label class="field">Razlog<textarea name="reason" minlength="10" required placeholder="Opiši problem sa oglasom…"></textarea></label><button class="btn" type="submit">Evidentiraj prijavu</button></form>`);break;
 case 'simulate':{const result=commit(s=>D.simulate(s,id,target.dataset.type));render();toast(result.duplicate?'Ponovljen događaj je zanemaren. Nema duplog knjiženja.':'Testni BEX događaj je evidentiran.');break;}
 case 'duplicate':{const o=D.order(S,id),last=o.events.slice().reverse().find(x=>o.eventIds.includes(x.id));if(!last)throw Error('Najpre pošalji jedan BEX testni događaj.');commit(s=>D.simulate(s,id,last.type,last.id));render();toast('Isti događaj je ponovljen i bezbedno zanemaren.');break;}
 case 'advance-day':commit(s=>{s.clock+=864e5;D.audit(s,'DEMO','CLOCK_ADVANCED','Testni sat +1 dan.');});render();toast('Testni sat je pomeren za jedan dan.');break;
 case 'demo-proof':commit(s=>D.addEvidence(s,id,[{name:'Demo foto dokaz: predmet, zaštita i paket',demo:true}]));render();toast('Dodat je jasno označen demo dokaz pakovanja.');break;
 case 'complaint':ui.complaintPhotos=[];openModal('Prijavi problem sa porudžbinom.','Pre neizvršene isplate pokreće se zahtev za zadržavanje.',`<form id="complaint-form" data-id="${e(id)}" class="stack"><div data-error></div><label class="field">Razlog<select name="reason" required><option value="">Izaberi razlog</option>${['Predmet nije primljen','Predmet je oštećen','Pogrešan predmet','Nedostaju delovi','Stanje odstupa od opisa','Sumnja na falsifikat ili prevaru'].map(r=>'<option>'+r+'</option>').join('')}</select></label><label class="field">Opis problema<textarea name="description" required minlength="10" maxlength="2000" placeholder="Šta se dogodilo? Navedi konkretne detalje."></textarea></label><label class="field">Dokazi (opciono)<input type="file" data-upload="complaint" accept="image/jpeg,image/png,image/webp" multiple></label><div id="complaint-photos" class="photo-list"></div><button class="btn" type="submit">Otvori testnu reklamaciju</button></form>`);break;
 case 'order-tab':ui.orderTab=id;render();break;
 case 'seller-tab':ui.sellerTab=id;render();break;
 case 'toggle-listing':commit(s=>{const l=s.listings.find(l=>l.id===id);if(l.seller!=='me'||!['ACTIVE','PAUSED'].includes(l.status))throw Error('Oglas nije moguće menjati.');l.status=l.status==='ACTIVE'?'PAUSED':'ACTIVE';D.audit(s,'me','LISTING_STATUS',l.status,id);});render();break;
 case 'edit-listing':{const l=S.listings.find(l=>l.id===id);openModal('Izmeni svoj oglas.','Izmena je moguća dok predmet nije rezervisan.',`<form id="edit-listing-form" data-id="${e(id)}" class="stack"><div data-error></div><label class="field">Naziv<input name="title" value="${e(l.title)}" required minlength="5" maxlength="100"></label><label class="field">Cena (RSD)<input name="price" value="${l.price/100}" inputmode="decimal" required></label><label class="field">Opis<textarea name="description" required minlength="20" maxlength="3000">${e(l.description)}</textarea></label><button class="btn" type="submit">Sačuvaj izmenu</button></form>`);break;}
 case 'listing-back':rememberDraft();ui.draft.step--;render();break;
 case 'save-draft':rememberDraft();commit(s=>s.draft=D.clone(ui.draft));toast('Nacrt je sačuvan u ovom pregledaču.');break;
 case 'demo-photo':rememberDraft();ui.draft.photos=['demo'];render();toast('Dodata je demo ilustracija predmeta.');break;
 case 'remove-photo':rememberDraft();ui.draft.photos.splice(Number(target.dataset.index),1);render();break;
 case 'suggest-description':{const form=$('#listing-form'),title=form.elements.title.value.trim();if(!title)throw Error('Najpre napiši naziv predmeta.');form.elements.description.value=title+'. Predmet je očuvan i funkcionalan. U opisu dopuni šta dolazi u paketu, koliko je korišćen i da li ima nedostatke. Šaljem pažljivo upakovano preko BEX-a.';toast('Dodat je demo predlog. Proveri i prilagodi opis pre objave.');break;}
 case 'promote':{const own=S.listings.filter(l=>l.seller==='me'&&l.status==='ACTIVE');if(!own.length)throw Error('Najpre postavi svoj aktivan oglas.');const p=S.config.plans.find(p=>p.id===id);openModal('Isprobaj paket '+e(p.name)+'.','Simulirana aktivacija bez naplate.',`<form id="promote-form" data-id="${e(id)}" class="stack"><div data-error></div><label class="field">Izaberi oglas<select name="listing">${own.map(l=>'<option value="'+e(l.id)+'">'+e(l.title)+'</option>').join('')}</select></label>${alertBox(D.money(p.price)+' · '+p.days+' dana. Ovo je testna cena i promocija se ne naplaćuje.','orange','spark')}<button class="btn" type="submit">Aktiviraj demo promociju</button></form>`);break;}
 case 'verify':verificationModal(id);break;
 case 'unverify':commit(s=>{s.users.me[id]=false;D.audit(s,'DEMO','VERIFICATION_REMOVED',id);});closeModal();render();toast('Demo potvrda je uklonjena.');break;
 case 'foreign-bank':commit(s=>{s.users.me.bankOwner='Drugo Test Lice';s.users.me.bank=false;D.audit(s,'DEMO','FOREIGN_ACCOUNT_REJECTED','Račun ne pripada prodavcu.');});render();toast('Račun drugog lica nije verifikovan. Isplata je blokirana.');break;
 case 'data-request':commit(s=>{s.dataRequests.push({id:D.uid('req'),type:'DELETE',at:D.now(),status:'PENDING_REVIEW'});D.audit(s,'me','DATA_REQUEST','Testni zahtev za brisanje podataka.');});toast('Testni zahtev je evidentiran za pregled. Podaci nisu obrisani.');render();break;
 case 'admin-login':setRole('admin','admin/overview');break;
 case 'moderate':if(!D.can(S,'moderate'))throw Error('Ova uloga nema pravo moderacije.');openModal('Odluka o oglasu.','Obrazloženje se čuva u revizijskom tragu.',`<form id="moderation-form" data-id="${e(id)}" data-decision="${e(target.dataset.decision)}" class="stack"><div data-error></div><label class="field">Obrazloženje<textarea name="reason" minlength="10" required placeholder="Razlog odluke…"></textarea></label><button type="submit" class="btn">${target.dataset.decision==='approve'?'Odobri objavu':'Ukloni oglas'}</button></form>`);break;
 case 'statement':commit(s=>{D.requirePermission(s,'reconcile');s.statement=s.orders.filter(o=>o.codStatus==='COLLECTED').map(o=>({orderId:o.id,amount:o.total}));D.audit(s,'ADMIN:'+s.session.adminRole,'DEMO_STATEMENT','Generisan testni BEX izvod.');});render();break;
 case 'statement-mismatch':commit(s=>{D.requirePermission(s,'reconcile');if(!s.statement?.length)throw Error('Izvod nema COD transakcije.');s.statement[0].amount+=10000;D.audit(s,'DEMO','STATEMENT_MISMATCH','Dodata probna razlika +100 RSD.');});render();break;
 case 'reconcile':commit(s=>{D.requirePermission(s,'reconcile');const differences=s.statement.filter(x=>x.amount!==s.ledger.filter(l=>l.orderId===x.orderId&&l.type==='COD').reduce((a,l)=>a+l.amount,0));D.audit(s,'ADMIN:'+s.session.adminRole,'RECONCILIATION','Broj razlika: '+differences.length);});toast('Provera je evidentirana. Razlike ostaju vidljive za ručni pregled.');break;
 case 'export-ledger':if(S.session.role!=='admin'||!['super','finance','auditor'].includes(S.session.adminRole))throw Error('Nedovoljno ovlašćenje za finansijski izvoz.');download('eBex_finansijska_evidencija.csv',csv([['Vreme','Porudžbina','Tip','Iznos RSD','Dugovna strana','Potražna strana','Referenca'],...S.ledger.map(x=>[x.at,x.orderId,x.type,x.amount/100,x.debit,x.credit,x.ref])]),'text/csv;charset=utf-8');break;
 case 'export-audit':if(S.session.role!=='admin')throw Error('Potreban je administratorski nalog.');download('eBex_revizijski_trag.csv',csv([['Vreme','Akter','Radnja','Opis','Referenca'],...S.audit.map(x=>[x.at,x.actor,x.action,x.detail,x.ref])]),'text/csv;charset=utf-8');break;
 case 'scenario':scenario(id);break;
 case 'run-tests':ui.tests=window.runEBTests();render();toast('Provere završene: '+ui.tests.filter(t=>t.pass).length+'/'+ui.tests.length+'.',ui.tests.some(t=>!t.pass));break;
 case 'export':download('eBex_testni_podaci_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(S,null,2));toast('Testni podaci su izvezeni kao JSON.');break;
 case 'reset':openModal('Vrati početne testne podatke?','Sačuvaj svoje testiranje pre vraćanja početnog stanja.',`<div class="stack"><p class="muted">Izvoz čuva trenutne oglase, razgovore i transakcije. Početno stanje će ponovo sadržati demo katalog i dve probne porudžbine.</p>${btn('Prvo izvezi JSON','export','','secondary')}${btn('Vrati demo podatke','confirm-reset')}${btn('Zadrži trenutno stanje','close','','ghost')}</div>`);break;
 case 'confirm-reset':{const before=D.clone(S);download('eBex_rezervna_kopija_pre_reseta.json',JSON.stringify(before,null,2));commit(s=>{const fresh=D.seed();Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,fresh);});Object.assign(ui,{query:'',category:'all',limit:8,tests:[],checkout:null});closeModal();go('market');toast('Početni podaci su vraćeni. Prethodno stanje je izvezeno u JSON.');break;}
 case 'label':{const o=D.order(S,id);download('eBex_TEST_nalepnica_'+id+'.html',`<!doctype html><html lang="sr-Latn"><meta charset="utf-8"><title>Testna nalepnica</title><style>body{font:16px Arial;margin:45px;color:#222}.label{max-width:600px;border:2px solid #222;padding:30px}h1{font-size:25px}h2{font-size:17px}.test{border:3px solid #b44;padding:15px;color:#b44;font-weight:bold}small{color:#777}</style><div class="label"><div class="test">TEST · NIJE VAŽEĆA BEX NALEPNICA</div><h1>eBex · ${e(id)}</h1><h2>${e(o.snapshot.title)}</h2><p>Referenca: ${e(o.shipment)}</p><p>Testno pouzeće: ${D.money(o.total)}</p><p>Test primalac: ${e(o.address?.name||'Demo kupac')}</p><p>${e(o.address?.street||'Test adresa')} · ${e(o.address?.city||'Test grad')}</p><small>Bez validnog barkoda. Ne koristiti za stvarno slanje.</small></div></html>`,'text/html;charset=utf-8');break;}
 case 'review':openModal('Kako je prošla kupovina?','Ocena je dozvoljena samo za završenu testnu transakciju.',`<form id="review-form" data-id="${e(id)}" class="stack"><div data-error></div><label class="field">Ocena<select name="rating"><option value="5">5 · Odlično</option><option value="4">4 · Veoma dobro</option><option value="3">3 · Dobro</option><option value="2">2 · Loše</option><option value="1">1 · Veoma loše</option></select></label><label class="field">Komentar<textarea name="comment" maxlength="500" required minlength="5"></textarea></label><p class="small muted">Ocena se čuva lokalno. Obostrano objavljivanje ocena nije uključeno u ovaj prototip.</p><button class="btn" type="submit">Sačuvaj testnu ocenu</button></form>`);break;
 default:toast('Radnja nije prepoznata.',true);
 }}catch(err){toast(err.message,true);}
});

function verificationModal(kind){const titles={phone:'Telefon',email:'E-mail',identity:'Identitet',bank:'Račun za isplatu'};let fields='';if(kind==='phone')fields='<label class="field">Demo SMS kod<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="123456" required autocomplete="off"></label>'+alertBox('Demo kod je <b>123456</b>. SMS se ne šalje. Posle 5 pogrešnih pokušaja blokira se provera na 60 sekundi.','orange','info');else if(kind==='bank')fields='<label class="field">Ime vlasnika testnog računa<input name="owner" value="'+e(S.users.me.bankOwner||S.users.me.name)+'" required maxlength="80"></label>'+alertBox('Ne unosi stvaran broj računa. Proveravamo samo princip: ime vlasnika mora odgovarati prodavcu.','orange','wallet');else fields=alertBox(kind==='email'?'Potvrđuješ samo testni status e-maila. Ne unosi se adresa i nema slanja poruke.':'Potvrđuješ samo testni KYC status. Ne prikupljaju se dokumenta ni biometrijski podaci.','orange','shield');openModal(titles[kind]+' · testna verifikacija.','Odvojen status verifikacije, bez stvarnih servisnih poziva.',`<form id="verify-form" data-id="${kind}" class="stack"><div data-error></div>${fields}<label class="checkline"><input type="checkbox" name="consent" required>Razumem da je ovo simulirana verifikacija.</label><button class="btn" type="submit">Potvrdi demo status</button>${S.users.me[kind]?btn('Ukloni postojeću demo potvrdu','unverify','data-id="'+kind+'"','ghost'):''}</form>`);}
document.addEventListener('submit',ev=>{
 const form=ev.target;if(!(form instanceof HTMLFormElement))return;ev.preventDefault();const f=Object.fromEntries(new FormData(form));const id=form.dataset.id;
 try{switch(form.id){
 case 'search-form':ui.query=String(f.q||'').trim();ui.limit=8;go('market');render();break;
 case 'filter-form':if((f.min&&(!Number.isFinite(amount(f.min))||amount(f.min)<0))||(f.max&&(!Number.isFinite(amount(f.max))||amount(f.max)<0)))throw Error('Unesi važeće iznose u RSD.');if(f.min&&f.max&&amount(f.min)>amount(f.max))throw Error('Donja cena ne može biti viša od gornje.');Object.assign(ui,{min:f.min,max:f.max,condition:f.condition,city:f.city,mode:f.mode,limit:8});render();break;
 case 'checkout-form':{if(!f.terms)throw Error('Potvrdi pravila testne kupovine.');if(!ui.checkout)throw Error('Ponovo otvori kupovinu.');const c=ui.checkout,o=commit(s=>D.createOrder(s,{listingId:c.id,offerId:c.offerId,address:{name:f.name.trim(),street:f.street.trim(),city:f.city.trim(),postal:f.postal.trim()},delivery:f.delivery,requestId:c.requestId}));ui.checkout=null;go('orders/'+o.id);toast('Testna kupovina je potvrđena. BEX pošiljka je simulirana.');break;}
 case 'message-form':commit(s=>D.sendMessage(s,id,String(f.message||'')));render();break;
 case 'offer-form':commit(s=>D.makeOffer(s,id,amount(f.price)));closeModal();render();toast('Ponuda je poslata. Promeni ulogu da je prihvati druga strana.');break;
 case 'complaint-form':commit(s=>D.complain(s,id,f.reason,f.description,ui.complaintPhotos||[]));closeModal();render();toast('Reklamacija je otvorena i finansijski status ažuriran.');break;
 case 'dispute-decision':commit(s=>D.decide(s,id,f.decision,f.reason));render();toast('Odluka je evidentirana sa obrazloženjem.');break;
 case 'listing-form':{rememberDraft(form);if(ui.draft.step===1){if(!ui.draft.photos.length)throw Error('Dodaj fotografiju ili izaberi demo ilustraciju.');if(ui.draft.title.trim().length<5||ui.draft.description.trim().length<20)throw Error('Dopuni naslov i opis.');ui.draft.step=2;render();}else if(ui.draft.step===2){if(!Number.isSafeInteger(ui.draft.price)||ui.draft.price<=0)throw Error('Unesi važeću cenu u RSD.');ui.draft.step=3;render();}else{const l=commit(s=>{const l=D.publish(s,{...ui.draft,ownership:!!f.ownership,art:categoryArt(ui.draft.category)});delete s.draft;return l;});ui.draft={step:1,photos:[],category:'tech',mode:'buy',condition:'Kao novo',city:'Beograd',weight:1,dims:[30,20,15]};go('listing/'+l.id);toast(l.status==='ACTIVE'?'Oglas je objavljen besplatno.':'Oglas je zadržan za pregled zbog sadržaja.');}break;}
 case 'edit-listing-form':commit(s=>{const l=s.listings.find(l=>l.id===id);if(l.seller!=='me'||l.status!=='ACTIVE')throw Error('Oglas se više ne može menjati.');const price=amount(f.price);if(!Number.isSafeInteger(price)||price<=0)throw Error('Unesi važeću cenu.');l.title=f.title.trim();l.description=f.description.trim();l.price=price;const bad=D.contactViolation(l.title+' '+l.description);if(bad){l.status='PENDING_REVIEW';s.moderation.unshift({id:D.uid('mod'),listingId:id,reason:bad,status:'OPEN',at:D.now()});}D.audit(s,'me','LISTING_EDITED',l.title,id);});closeModal();render();toast('Izmene oglasa su sačuvane.');break;
 case 'promote-form':commit(s=>D.promote(s,f.listing,id));closeModal();render();toast('Demo promocija je aktivna. Nema naplate.');break;
 case 'profile-form':commit(s=>{const u=s.users.me;const changed=u.name!==f.name.trim();u.name=f.name.trim();u.city=f.city.trim();u.bio=f.bio.trim();u.initials=u.name.split(/\s+/).slice(0,2).map(t=>t[0]).join('').toUpperCase();if(changed){u.identity=false;u.bank=false;}D.audit(s,'me','PROFILE_UPDATED',changed?'Promena imena resetuje identitet i račun.':'Izmena profila.');});render();toast('Profil je sačuvan.');break;
 case 'verify-form':{const t=Date.now();if(id==='phone'){if((ui.otpBlockedUntil||0)>t)throw Error('Sačekaj kraj testne blokade od 60 sekundi.');if(f.code!=='123456'){ui.otpAttempts=(ui.otpAttempts||0)+1;if(ui.otpAttempts>=5){ui.otpBlockedUntil=t+60000;ui.otpAttempts=0;}throw Error('Pogrešan demo kod. Ispravan kod je 123456.');}}if(!f.consent)throw Error('Potvrdi da je ovo simulacija.');commit(s=>{if(id==='bank'){if(D.normalized(f.owner.trim())!==D.normalized(s.users.me.name))throw Error('Račun trećeg lica se odbija. Ime vlasnika mora biti isto.');s.users.me.bankOwner=f.owner.trim();}s.users.me[id]=true;s.consents.push({kind:'DEMO_VERIFICATION',type:id,version:'prototype-1.1',at:D.now()});D.audit(s,'me','DEMO_VERIFICATION',id);});ui.otpAttempts=0;closeModal();render();toast('Testna verifikacija je potvrđena.');break;}
 case 'report-form':commit(s=>{if(f.reason.trim().length<10)throw Error('Dodaj konkretniji razlog prijave.');if(form.dataset.kind==='chat'&&f.block)s.conversations.find(c=>c.id===form.dataset.ref).blocked=true;D.audit(s,'me',form.dataset.kind==='chat'?'CHAT_REPORTED':'LISTING_REPORTED',f.reason,form.dataset.ref);});closeModal();render();toast('Prijava je evidentirana za testni pregled.');break;
 case 'moderation-form':commit(s=>{D.requirePermission(s,'moderate');const l=s.listings.find(l=>l.id===id);if(f.reason.trim().length<10)throw Error('Obrazloži odluku.');if(form.dataset.decision==='approve'){const bad=D.contactViolation(l.title+' '+l.description);if(bad)throw Error('Kontakt podaci moraju biti uklonjeni iz oglasa pre odobrenja.');l.status='ACTIVE';}else l.status='REMOVED';s.moderation.filter(m=>m.listingId===id).forEach(m=>m.status='RESOLVED');D.audit(s,'ADMIN:'+s.session.adminRole,'MODERATION_'+l.status,f.reason,id);});closeModal();render();toast('Moderatorska odluka je sačuvana.');break;
 case 'config-form':commit(s=>{if(s.session.role!=='admin'||s.session.adminRole!=='super')throw Error('Poslovna pravila menja super administrator.');for(const k of ['shippingBase','shippingPerKg','shopDiscount','proofThreshold']){const n=amount(f[k]);if(!Number.isSafeInteger(n)||n<0)throw Error('Proveri cene i pragove.');s.config[k]=n;}for(const k of ['maxKg','maxCm','dispatchHours','payoutDays']){const n=Number(f[k]);if(!Number.isFinite(n)||n<=0)throw Error('Proveri mase, dimenzije i rokove.');s.config[k]=n;}s.config.holdSupported=!!f.holdSupported;s.configVersion=(s.configVersion||1)+1;D.audit(s,'ADMIN:super','CONFIG_CHANGED','Verzija '+s.configVersion);});render();toast('Testna konfiguracija je sačuvana. Postojeće porudžbine zadržavaju ugovorene iznose.');break;
 case 'plans-form':commit(s=>{if(s.session.role!=='admin'||s.session.adminRole!=='super')throw Error('Katalog menja super administrator.');for(const p of s.config.plans){const price=amount(f[p.id+'_price']),days=Number(f[p.id+'_days']);if(!Number.isSafeInteger(price)||price<0||!Number.isInteger(days)||days<1||days>365)throw Error('Proveri cene i trajanje paketa.');Object.assign(p,{name:f[p.id+'_name'].trim(),price,days,description:f[p.id+'_description'].trim()});}D.audit(s,'ADMIN:super','PREMIUM_CONFIG','Izmenjen testni katalog.');});render();toast('Premium katalog je ažuriran.');break;
 case 'review-form':commit(s=>{const o=D.order(s,id);if(o.status!=='COMPLETED'||s.ratings.some(r=>r.orderId===id))throw Error('Ocena je dozvoljena jednom za završenu transakciju.');const bad=D.contactViolation(f.comment);if(bad)throw Error(bad);s.ratings.push({orderId:id,rating:Number(f.rating),comment:f.comment,at:D.now()});D.audit(s,'me','RATING_CREATED',f.rating+' zvezdica',id);});closeModal();render();toast('Testna ocena je sačuvana.');break;
 }}catch(err){formError(form,err);}
});
document.addEventListener('change',async ev=>{
 const el=ev.target;try{
 if(el.dataset.change==='sort'){ui.sort=el.value;render();}
 else if(el.dataset.change==='admin-role'){commit(s=>{s.session.adminRole=el.value;D.audit(s,'DEMO','ADMIN_ROLE_CHANGED',el.value);});render();}
 else if(el.dataset.change==='delivery'){if(ui.checkout){ui.checkout.delivery=el.value;const l=S.listings.find(l=>l.id===ui.checkout.id);$('#shipping-summary').textContent=D.money(D.quote(S,l.weight,el.value));$('#total-summary').textContent=D.money(ui.checkout.price+D.quote(S,l.weight,el.value));}}
 if(el.dataset.upload){
  const kind=el.dataset.upload,files=Array.from(el.files||[]);if(!files.length)return;
  if(kind==='import'){if(files[0].size>12e6)throw Error('JSON izvoz je prevelik.');const raw=await files[0].text(),loaded=D.validateImport(JSON.parse(raw));if(!Array.isArray(loaded.favorites)||!Array.isArray(loaded.notifications)||!Array.isArray(loaded.moderation)||!Array.isArray(loaded.config.plans)||!loaded.session)throw Error('Testni izvoz nema potrebne sekcije.');if(/"(?:__proto__|constructor|prototype)"\s*:/.test(raw))throw Error('Nevažeća polja testnog izvoza.');download('eBex_kopija_pre_uvoza.json',JSON.stringify(S,null,2));commit(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,loaded);D.audit(s,'DEMO','IMPORT','Uvezen testni JSON.');});go('test');render();toast('Uvezeni su testni podaci. Prethodno stanje je sačuvano kao JSON.');return;}
  if(files.length>5)throw Error('Dodaj najviše 5 fotografija odjednom.');
  if(kind==='listing')rememberDraft();
  const photos=[];for(const file of files)photos.push(await readPhoto(file));
  if(kind==='listing'){if(ui.draft.photos.length+photos.length>5)throw Error('Oglas može imati najviše 5 fotografija.');ui.draft.photos.push(...photos.map(p=>p.data));render();}
  else if(kind==='proof'){commit(s=>D.addEvidence(s,el.dataset.id,photos));render();toast('Fotografije pakovanja su dodate.');}
  else if(kind==='complaint'){ui.complaintPhotos=photos;$('#complaint-photos').innerHTML=photos.map(p=>'<img src="'+e(p.data)+'" alt="'+e(p.name)+'">').join('');}
 }
 }catch(err){toast(err.message,true);el.value='';}
});
document.addEventListener('input',ev=>{if(ev.target.id==='audit-search')$('#audit-rows').innerHTML=auditRows(ev.target.value);});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){closeModal();$('.menu-pop')?.remove();}if(ev.key==='Tab'&&$('#modals .modal')){const els=Array.from($('#modals .modal').querySelectorAll('button,a[href],input,select,textarea')).filter(el=>!el.disabled&&el.offsetParent!==null);if(!els.length)return;const first=els[0],last=els[els.length-1];if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();ui.listingPhoto=null;render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',ev=>{if(ev.key===STORAGE&&ev.newValue){try{S=D.validateImport(JSON.parse(ev.newValue));toast('Testni podaci su promenjeni u drugoj kartici. Osveži prikaz ako je potrebno.');}catch(err){toast('Podaci iz druge kartice nisu ispravni.',true);}}});
if(S.draft)ui.draft=D.clone(S.draft);
if(!location.hash)location.hash='/market';else render();
})();
